INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0914', 'spa', 'Separar, apartar (Hifil); ser separado, retirarse (Nifal); distinguir entre lo santo y lo profano (Hifil)', 'Separar, apartar (Hifil); ser separado, retirarse (Nifal); distinguir entre lo santo y lo profano (Hifil)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0919', 'spa', 'Brecha, grieta, fisura — daño estructural en un muro o edificio que requiere reparación, especialmente en la restauración del templo. El sustantivo בֶ', 'Brecha, grieta, fisura — daño estructural en un muro o edificio que requiere reparación, especialmente en la restauración del templo. El sustantivo בֶּדֶק (bedeq) designa una brecha, fisura o abertura en una estructura, el tipo de deterioro que exige reparación de albañilería. Casi todas las apariciones se concentran en 2 Reyes 12, donde el joven rey Joás organiza el financiamiento y la ejecución de las reparaciones del templo tras años de abandono bajo regímenes anteriores. La expresión repetida בֶּדֶק הַבַּיִת (''brecha de la casa/templo'') se convierte prácticamente en un término técnico para las obras de restauración estructural. Ezequiel 27:9 y 27:27 extienden la imagen al calafateo de barcos, donde los ancianos de Biblos reparan las ''brechas'' de las naves mercantes de Tiro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0922', 'spa', 'vacío, nada, desolación; emparejado con תֹּהוּ para describir el caos primordial o la desolación del juicio', 'Término poético que designa el vacío o la nada, y que aparece casi exclusivamente en la expresión «תֹּהוּ וָבֹהוּ» (sin forma y vacía). Génesis 1:2 describe la tierra previa a la creación con esa frase. Jeremías emplea la misma expresión para retratar la tierra bajo el juicio divino, devuelta al caos (Jeremías 4:23). Isaías la usa metafóricamente: Dios extenderá sobre Edom «el cordel de תֹּהוּ y las piedras de בֹּהוּ», invirtiendo la imagen del constructor hacia la destrucción (Isaías 34:11). La palabra evoca el caos primordial o la anulación escatológica del orden creado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0926', 'spa', 'Aterrorizarse o consternarse; aterrorizar o alarmar a alguien; apresurarse, actuar precipitadamente', 'Aterrorizarse o consternarse; aterrorizar o alarmar a alguien; apresurarse, actuar precipitadamente');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0927', 'spa', 'Alarmar, aterrorizar o consternar; también usado adverbialmente como ''apresuradamente'', transmitiendo urgencia nacida de la alarma. Arameo, presente ú', 'Alarmar, aterrorizar o consternar; también usado adverbialmente como ''apresuradamente'', transmitiendo urgencia nacida de la alarma. Arameo, presente únicamente en Daniel. Verbo arameo que aparece exclusivamente en el libro de Daniel, donde las visiones de Dios producen un terror visceral. El tronco Pael capta el impacto psicológico de la revelación divina: los pensamientos de Nabucodonosor ''lo turbaron'' (Dn 4:19), y el propio Daniel quedó ''consternado'' por las visiones de las cuatro bestias (Dn 7:15, 28). El terror de Belsasar ante la escritura en la pared se describe con la misma raíz — su rostro cambió y sus señores se ''alarmaron'' (Dn 5:6, 9-10). El infinitivo Hitpael desarrolla un sentido adverbial ''apresuradamente'', usado cuando Arioc lleva a Daniel ''con prisa'' ante el rey (Dn 2:25) y cuando Darío corre ''apresuradamente'' al foso de los leones (Dn 6:19) — urgencia que brota de la alarma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0928', 'spa', 'Terror repentino, espanto o calamidad — ruina alarmante que golpea sin previo aviso', 'Designa un terror súbito y abrumador, o una ruina catastrófica que sobrecoge a sus víctimas con rapidez impactante. En Levítico 26:16 encabeza una lista de maldiciones del pacto que Dios impondrá a los desobedientes. El Salmo 78:33 lo empareja con la futilidad: años consumidos «en terror repentino». Isaías 65:23 promete que los redimidos no engendrarán hijos «para calamidad», revirtiendo así la maldición. El cognado asirio beltu («terror») confirma el pavor visceral que esta palabra transmite. Las traducciones multilingües apuntan uniformemente a un miedo desestabilizador y alarmante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0929', 'spa', 'Bestia, animal, ganado — criatura terrestre grande, salvaje o domesticada; colectivamente, ganado o animales en general.', 'בְּהֵמָה es uno de los términos zoológicos más comunes de la Biblia hebrea, cubriendo desde las bestias salvajes hasta el ganado de labranza. En los relatos de la creación (Gn 1:24-25), designa toda una categoría de criaturas terrestres distinta de las aves y los reptiles. Sin embargo, en las leyes sobre el descanso sabático (Éx 20:10) y la propiedad (Gn 36:6), la misma palabra se estrecha para referirse al ganado doméstico — las reses y el ganado del que depende una familia. Las traducciones alemanas lo ilustran con nitidez: ''Tier'' para la bestia genérica, pero ''Vieh'' para el ganado en propiedad. El célebre plural בְּהֵמוֹת en Job 40:15 recurre a la acepción más amplia de este vocablo para nombrar a una criatura de poder incomprensible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0931', 'spa', 'Sustantivo que se refiere al pulgar de la mano o al dedo gordo del pie, apareciendo siempre en contextos rituales donde ambas extremidades se nombran ', 'Sustantivo que se refiere al pulgar de la mano o al dedo gordo del pie, apareciendo siempre en contextos rituales donde ambas extremidades se nombran juntas. En la consagración de Aarón y sus hijos, la sangre de la ofrenda se aplica al pulgar derecho y al dedo gordo del pie derecho (Éx 29:20; Lv 8:23-24). El mismo ritual aparece en la purificación de leprosos sanados, donde el aceite y la sangre marcan estas extremidades como señales de limpieza (Lv 14:14, 17, 25, 28). Fuera de la ley ritual, la forma plural aparece llamativamente en Jueces 1:6-7, donde los pulgares y dedos gordos cortados de Adoni-bezec se convierten en evidencia de justicia retributiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0934', 'spa', 'baheret -- mancha brillante o blanca en la piel, signo diagnóstico en las leyes levíticas de pureza para enfermedades cutáneas', 'baheret -- mancha brillante o blanca en la piel, signo diagnóstico en las leyes levíticas de pureza para enfermedades cutáneas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0935', 'spa', 'Venir, llegar, entrar; en Hifil, traer; en Hofal, ser traído. Uno de los verbos de movimiento más frecuentes del hebreo.', 'בּוֹא es el verbo hebreo por excelencia de la llegada y la entrada, tan frecuente que aparece en casi todos los capítulos de la Biblia hebrea. En su sentido básico describe movimiento hacia un punto de referencia: Abraham ''vino'' a Hebrón (Gn 13:18), los visitantes ''llegaron'' a Sodoma (Gn 19:1). Pero בּוֹא también se especializa para cruzar un umbral — ''entrar'' en el arca, una ciudad o la tierra prometida — y en este sentido contrasta con יָצָא (''salir''). El Hifil causativo lo transforma en verbo de acarreo: los hermanos de José ''trajeron'' regalos (Gn 43:26) y Dios ''introdujo'' a Israel en Canaán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0936', 'spa', 'buz -- despreciar, menospreciar, tener en poco; tratar con desdén como algo sin valor o indigno de consideración', 'buz -- despreciar, menospreciar, tener en poco; tratar con desdén como algo sin valor o indigno de consideración');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0937', 'spa', 'Desprecio, desdén — el rechazo desdeñoso de una persona o cosa considerada indigna o vergonzosa. El sustantivo בּוּז (buz) denota la actitud y expresi', 'Desprecio, desdén — el rechazo desdeñoso de una persona o cosa considerada indigna o vergonzosa. El sustantivo בּוּז (buz) denota la actitud y expresión del desprecio — el rechazo desdeñoso de alguien considerado sin valor. En la literatura sapiencial, Job describe cómo los prósperos amontonan desprecio sobre el que tropieza (Job 12:5) y cómo incluso los marginados lo desprecian (Job 12:21). Confiesa su temor al desprecio de la multitud (Job 31:34). El salmista suplica ser librado del desprecio y el oprobio (Sal 31:18; 119:22) y clama como alguien que ''está más que harto del escarnio de los que viven cómodamente'' (Sal 123:3-4). Génesis 38:23 lo usa de forma más leve — Judá prefiere dejar que Tamar se quede con su prenda antes de que ''seamos objeto de burla''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0938', 'spa', 'Buz, nombre propio y tribal; hijo de Nacor, asociado con tribus árabes del norte', 'Nombre que lleva el segundo hijo de Nacor, sobrino de Abraham, y la tribu árabe que desciende de él. Buz aparece en la genealogía de la familia extendida de Abraham (Génesis 22:21). La tribu de Buz se menciona junto a Dedán y Tema en el oráculo de Jeremías contra los pueblos árabes (Jeremías 25:23), lo que sugiere una ubicación en el norte de Arabia. Además, un gadita llamado Buz figura en Crónicas (1 Crónicas 5:14). El nombre vincula la genealogía patriarcal con la geografía tribal posterior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0943', 'spa', 'estar confuso, perplejo o desorientado (Nifal); vagar sin rumbo por aturdimiento', 'Verbo en la conjugación pasiva (Nifal) que describe confusión o desconcierto. Faraón pensará que los israelitas están «confusos», vagando sin rumbo por el desierto, atrapados por la geografía (Éxodo 14:3). La ciudad de Susa queda «aturdida» ante el edicto de Amán contra los judíos (Ester 3:15). Joel describe al ganado deambulando confundido porque la sequía ha destruido los pastos (Joel 1:18). El término abarca la desorientación mental, la confusión espacial y el caos que sobreviene cuando el orden habitual se desmorona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0947', 'spa', 'Pisotear, hollar, revolcarse; de guerreros que pisotean enemigos, destrucción intensiva, revolcarse en sangre, o ser pisoteado', 'Pisotear, hollar, revolcarse; de guerreros que pisotean enemigos, destrucción intensiva, revolcarse en sangre, o ser pisoteado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0948', 'spa', 'Biso; tela fina de lino blanco usada para vestiduras sacerdotales, cortinas del templo y ropajes reales.', 'Se refiere al biso, un lino blanco de alta calidad apreciado en el antiguo Cercano Oriente por su finura y resplandor. Aparece exclusivamente en textos bíblicos tardíos — Crónicas, Esdras y Ester — para describir las vestiduras sacerdotales, la indumentaria de los cantores levitas y el velo del templo (2 Cr 3:14). El español lino fino y el francés fin lin apuntan a ''lino fino'', mientras que el alemán Byssus conserva el préstamo técnico. El término probablemente ingresó al hebreo desde el egipcio (cf. hbos, ''vestir'') y está estrechamente emparentado con el arameo bus. Su asociación con el culto, la realeza y la artesanía sagrada subraya la dignidad ceremonial de quienes lo vestían o lo trabajaban (1 Cr 4:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0953a', 'spa', 'Pozo, cisterna o calabozo; una cavidad excavada en el suelo usada para almacenar agua, atrapar, confinar, o como figura del Seol.', 'Pozo, cisterna o calabozo; una cavidad excavada en el suelo usada para almacenar agua, atrapar, confinar, o como figura del Seol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0954', 'spa', 'Avergonzarse, sentir deshonra; causar vergüenza (Hifil); tardar, demorarse (Piel); rara vez secarse', 'Verbo profundamente emocional arraigado en la experiencia de la desgracia pública y la confianza defraudada. En su forma Qal predominante, describe la sensación interna de vergüenza, ya sea ante Dios (Esd 9:6), ante los enemigos (Sal 6:10) o frente al fracaso moral. El Hifil causativo expresa el acto de avergonzar activamente a otro, como cuando el salmista declara que Dios ha avergonzado a los malhechores (Sal 14:6). Un desarrollo semántico sorprendente aparece en el Piel, donde la raíz pasa a significar «tardar» o «demorar», como cuando Israel se impacientó porque Moisés tardaba en bajar del Sinaí (Éx 32:1). Una única ocurrencia en Oseas 13:15 apunta al significado de secarse, posiblemente vinculado al marchitamiento que acompaña la deshonra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0955', 'spa', 'Vergüenza, deshonra — la humillación sufrida o impuesta mediante exposición pública o derrota', 'Sustantivo que expresa la dolorosa experiencia de vergüenza y deshonra pública. Aparece en contextos de humillación nacional y descrédito personal: el salmista cubierto de vergüenza (Sal 89:45), el horror del oprobio cubriendo los rostros durante el juicio (Ez 7:18), la desgracia de Esaú por la violencia contra su hermano (Abd 1:10), y la vergüenza del enemigo cuando Dios vindica a Israel (Miq 7:10). La palabra pertenece a una rica familia léxica hebrea centrada en la raíz בּוֹשׁ, y las evidencias multilingües convergen en una profunda deshonra social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0957', 'spa', 'Despojo, botín, presa; bienes tomados por la fuerza en guerra o incursiones, también aplicado a personas tratadas como presa', 'Despojo, botín, presa; bienes tomados por la fuerza en guerra o incursiones, también aplicado a personas tratadas como presa');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0959', 'spa', 'Despreciar, tener en poco; en forma pasiva, ser menospreciado o tenido por insignificante', 'Despreciar, tener en poco; en forma pasiva, ser menospreciado o tenido por insignificante');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0961', 'spa', 'Botín, despojo, saqueo — bienes materiales arrebatados a los enemigos derrotados en la guerra o en incursiones. El sustantivo femenino בִּזָּה (bizzah', 'Botín, despojo, saqueo — bienes materiales arrebatados a los enemigos derrotados en la guerra o en incursiones. El sustantivo femenino בִּזָּה (bizzah) denota el botín, despojo o saqueo tomado de los enemigos vencidos. Aparece exclusivamente en textos bíblicos tardíos — Crónicas, Ester, Nehemías, Daniel y una aparición en 1 Samuel — siempre refiriéndose a bienes materiales obtenidos mediante victoria militar o saqueo. Las fuerzas de Asa saquearon las ciudades circundantes tras derrotar a Zera el cusita (2 Cr 14:14), mientras que en Ester los judíos se abstuvieron deliberadamente de tocar el botín de sus enemigos muertos (Est 9:10, 15-16). Daniel 11:24 describe a un rey futuro que distribuye el botín entre sus seguidores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0962', 'spa', 'Saquear, tomar botín; como participio, saqueador; en voces pasivas, ser saqueado o despojado', 'Saquear, tomar botín; como participio, saqueador; en voces pasivas, ser saqueado o despojado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0966', 'spa', 'Bezec, topónimo; lugar de concentración militar y derrota del rey cananeo Adoni-bezec', 'Ciudad en la zona montañosa central que sirvió como punto de reunión militar. Judá derrotó a las fuerzas cananeas y ferezeas en Bezec y capturó allí al rey Adoni-bezec (Jueces 1:4-5). Saúl concentró al ejército israelita en Bezec antes de marchar a liberar Jabés de Galaad del asedio amonita (1 Samuel 11:8). El sitio, posiblemente la actual Khirbet Ibziq, se hallaba en una ruta entre las tierras altas centrales y el valle del Jordán, lo que le confería un valor estratégico para la concentración de tropas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0970', 'spa', 'Joven en la flor de la vida, en edad de combatir o casarse; raramente, escogido o elegido (de la raíz בחר, ''elegir'')', 'Joven en la flor de la vida, en edad de combatir o casarse; raramente, escogido o elegido (de la raíz בחר, ''elegir'')');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0971', 'spa', 'Torre de asedio; estructura militar empleada para atacar ciudades fortificadas', 'Este término poco frecuente aparece únicamente en el oráculo de Isaías contra Tiro, describiendo las torres de asedio que utilizaban los caldeos. Estas estructuras móviles permitían a los atacantes alcanzar la altura de las murallas para abrir brechas en las fortificaciones. La rareza de esta palabra y su significado técnico-militar la convierten en uno de los vocablos especializados del hebreo, conocido principalmente por quienes estaban familiarizados con la guerra de asedio. Su uso por parte de Isaías resalta el poder militar abrumador desplegado contra la orgullosa ciudad mercantil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0972', 'spa', 'Escogido, elegido; siempre referido a aquellos seleccionados por Dios para un propósito especial o relación de pacto', 'Escogido, elegido; siempre referido a aquellos seleccionados por Dios para un propósito especial o relación de pacto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0974', 'spa', 'Examinar, probar, poner a prueba; de Dios probando corazones humanos, humanos probando a Dios, y el ensayo del refinador de metales', 'Examinar, probar, poner a prueba; de Dios probando corazones humanos, humanos probando a Dios, y el ensayo del refinador de metales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0975', 'spa', 'atalaya, torre de asedio; estructura militar para observación o asalto', 'Término de fortificación que designa una atalaya o una torre de asedio, según el contexto. Isaías menciona «la colina y la atalaya» (Isaías 32:14) como lugares abandonados bajo el juicio divino. El difícil texto de Isaías 23:13 puede referirse a torres de asedio levantadas contra Tiro. La palabra presenta variantes textuales (ketiv/qere) que complican su identificación precisa, pero el sentido militar-arquitectónico es claro. Las torres cumplían funciones tanto defensivas (observación) como ofensivas (guerra de asedio), por lo que el contexto resulta decisivo para determinar cuál se indica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0977', 'spa', 'Elegir, seleccionar, preferir; de la elección soberana de Dios sobre personas y lugares; pasivo: escogido, electo', 'בָּחַר es el verbo principal de selección deliberada en la Biblia hebrea, y su peso teológico es inmenso. Cuando Dios «elige» a Israel (Dt 7:6), Jerusalén (1 R 11:13) o a David (1 S 16:8-10), el verbo porta toda la gravedad de la elección soberana: no una preferencia entre iguales, sino un acto decisivo de compromiso pactual. El participio pasivo בָּחוּר («escogido») se convierte prácticamente en un título: para guerreros de élite (Jue 20:15-16), para Israel como pueblo (Is 43:20) y en Proverbios para la sabiduría «escogida» por encima de la plata (Pr 8:10; 10:20). El español «escoger» y «elegir» captan bien este núcleo deliberativo y decisivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0979', 'spa', 'juventud, mocedad; el periodo de la vida temprana caracterizado por vigor y energía', 'Sustantivo abstracto en plural que designa la etapa de la juventud o la adultez temprana. Moisés describe a Josué como su servidor «desde su juventud» (Números 11:28). Eclesiastés exhorta al joven a alegrarse «en los días de tu juventud» y a recordar a Dios «en los días de tu mocedad» (Eclesiastés 11:9; 12:1). El término evoca la fase de la vida marcada por la energía, el potencial y las experiencias formativas, y aparece tanto en la narrativa histórica como en la literatura sapiencial para señalar la fugacidad de esta etapa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0980', 'spa', 'Bajurim, aldea benjaminita al este de Jerusalén, en el camino al Jordán, asociada a la huida de David ante Absalón.', 'Bajurim es un topónimo que designa una pequeña aldea en el territorio de Benjamín, situada al este del monte de los Olivos en el camino que desciende hacia el valle del Jordán. El lugar ocupa un papel destacado en la historia personal de David: Paltiel, esposo de Mical, la sigue llorando desde allí (2 Sam 3:16); Simei hijo de Gera maldice a David desde Bajurim durante la revuelta de Absalón (2 Sam 16:5); Jonatán y Ahimaas se ocultan en un pozo del pueblo mientras llevan información a David (2 Sam 17:18); y Salomón invoca más tarde el origen de Simei en Bajurim (1 Re 2:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0981', 'spa', 'Hablar precipitadamente, balbucear — proferir palabras sin reflexión ni deliberación adecuada', 'Describe un habla descuidada e impulsiva: palabras que escapan de los labios antes de que el pensamiento las alcance. Proverbios 12:18 contrasta al que «habla precipitadamente» con la lengua del sabio que trae sanidad. En Levítico 5:4 el verbo aparece dos veces en el contexto de juramentos temerarios: jurar irreflexivamente con los labios, sea para bien o para mal. El Salmo 106:33 lo aplica a Moisés, quien «habló precipitadamente» en Meribá cuando Israel provocó su espíritu. Las glosas multilingües subrayan de manera consistente la cualidad impulsiva y desprevenida del discurso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0982', 'spa', 'Confiar, apoyarse en, sentirse seguro; en Hifil, hacer que alguien confíe o se sienta confiado', 'Verbo fundamental de confianza y seguridad, בָּטַח abarca todo el espectro desde la confianza activa dirigida hacia Dios o protectores humanos, hasta un estado intransitivo de sentirse seguro o a salvo. El sentido Qal activo domina la Escritura, con más de cien apariciones en exhortaciones a confiar en el Señor (Sal 37:3; Pr 3:5). Sin embargo, el uso estativo advierte contra la complacencia: los habitantes de Lais vivían «seguros» y desprevenidos (Jue 18:7). El Hifil causativo, más raro pero teológicamente potente, describe a figuras como los adversarios de Ezequías que «hacen confiar» a otros en promesas falsas (2 R 18:30; Jer 28:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0983', 'spa', 'Seguridad, protección — usado adverbialmente para habitar, caminar o acostarse en un estado de confianza segura', 'Seguridad, protección — usado adverbialmente para habitar, caminar o acostarse en un estado de confianza segura');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0986', 'spa', 'confianza, seguridad; certeza depositada en alguien o en algo', 'Sustantivo que denota la confianza o seguridad puesta en alguien o en algo. El Rabsaces se burla de Ezequías preguntando: «¿Qué confianza es esta en la que confías?» (2 Reyes 18:19 = Isaías 36:4), cuestionando la base de la seguridad de Judá. Eclesiastés ofrece un proverbio: un perro vivo es mejor que un león muerto, pues al menos tiene esperanza (Eclesiastés 9:4). El término apunta al objeto de la confianza, ya sea esta mal depositada en alianzas humanas o bien fundada en Dios. La burla del asirio expone la fragilidad de toda confianza que no descanse en el Señor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0989', 'spa', 'Cesar, detenerse; (Pa''el) hacer cesar, obligar a detenerse — usado para detener obras o actividades por decreto.', 'Verbo arameo que aparece exclusivamente en Esdras, describiendo la paralización de la construcción del templo de Jerusalén. En su conjugación básica Pe''al significa simplemente ''cesar'' o ''detenerse'', como cuando la obra de reconstrucción se detuvo (Ezra 4:24). En la conjugación causativa Pa''el, describe la detención forzosa de los trabajos por funcionarios hostiles que obligaron a los judíos a dejar de construir. El español distingue ambas conjugaciones: ''cesar'' para la intransitiva y ''hacer cesar'' para la causativa, preservando claramente la distinción de voz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0990', 'spa', 'Vientre, abdomen, seno materno; la parte media del cuerpo, extendiéndose al útero como sede de la gestación e idiomáticamente al origen o nacimiento.', 'Vientre, abdomen, seno materno; la parte media del cuerpo, extendiéndose al útero como sede de la gestación e idiomáticamente al origen o nacimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0994', 'spa', 'bi -- por favor, te ruego; partícula de súplica usada al dirigirse a un superior o al hacer una petición humilde', 'bi -- por favor, te ruego; partícula de súplica usada al dirigirse a un superior o al hacer una petición humilde');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0995', 'spa', 'Entender, percibir, discernir; (Qal) captar; (Nifal) ser prudente; (Hifil) comprender, enseñar; (Hitpael) considerar', 'El hebreo בִּין abarca actos cognitivos que van desde la percepción simple hasta la sabiduría reflexiva. En Qal, significa percibir o entender algo con la mente o los sentidos. Las formas Nifal describen a una persona caracterizada por el entendimiento: discerniente, prudente. El Hifil cumple doble función: internamente, poseer entendimiento (estativo); causativamente, hacer que otro entienda (enseñar). El Hitpael añade deliberación reflexiva: considerar detenidamente, reflexionar, ponderar. El cognado árabe فَهِمَ y las traducciones coreanas que distinguen entre 깨닫다 (darse cuenta) y 이해하다 (comprender) ilustran su amplio espectro semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0996', 'spa', 'Entre, en medio de; preposición que marca el intervalo espacial, relacional o conceptual entre dos o más entidades', 'La preposición hebrea בֵּין marca el intervalo o espacio entre dos o más puntos, ya sean físicos, temporales o abstractos. Aparece más de 400 veces en la Biblia hebrea, estructurando distinciones tan fundamentales como la de la luz y las tinieblas (Gn 1:4) y la de las aguas de arriba y de abajo (Gn 1:6). Con sufijos pronominales y en construcciones como מִבֵּין («de entre»), transmite un posicionamiento relacional matizado. Los cognados en arameo, siríaco y árabe confirman su pedigrí pansemítico como la palabra por excelencia para «entre».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0997', 'spa', 'entre, en medio de (arameo); preposición espacial o relacional que indica posición intermedia', 'Preposición aramea que significa «entre» o «en medio de», presente en las visiones de Daniel. Aparece en descripciones de bestias simbólicas y sus rasgos: el oso levantado «de un lado» (literalmente «entre»), con costillas «entre sus dientes» (Daniel 7:5); un cuerno que surge «entre» los demás (Daniel 7:8). Funciona tanto espacial como relacionalmente, indicando posición dentro de un conjunto o ubicación respecto a límites. El arameo בֵּין es paralelo al hebreo בֵּין, con ligeras diferencias ortográficas (variantes ketiv/qeré conservadas en algunos manuscritos).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0998', 'spa', 'Entendimiento, discernimiento, perspicacia — la facultad cognitiva de percibir distinciones y captar sabiduría', 'Entendimiento, discernimiento, perspicacia — la facultad cognitiva de percibir distinciones y captar sabiduría');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1000', 'spa', 'Huevo o huevos, referido a nidos de aves, incubación de avestruces y metafóricamente a huevos de víbora que engendran maldad.', 'Sustantivo femenino que aparece solo en plural, referido a los huevos de diversas criaturas. En Deuteronomio 22:6 aparece en la ley humanitaria que prohíbe tomar a la madre junto con sus huevos. Job 39:14 se maravilla ante la avestruz que abandona sus huevos en el suelo. Isaías emplea los huevos en dos imágenes impactantes: recoger huevos abandonados de las naciones tan fácilmente como saquear un nido (Isa 10:14), y los malvados incubando huevos de víbora cuyas cáscaras mismas engendran serpientes (Isa 59:5). La evidencia multilingüe confirma un significado único y estable en todas las ocurrencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1002', 'spa', 'Término del hebreo bíblico tardío, probablemente tomado del acadio ''bīrtu'' (fortaleza) a través del persa. בִּירָה designa una gran estructura fortifi', 'Término del hebreo bíblico tardío, probablemente tomado del acadio ''bīrtu'' (fortaleza) a través del persa. בִּירָה designa una gran estructura fortificada. Aparece casi exclusivamente en la literatura postexílica — Ester, Nehemías, Daniel y Crónicas — reflejando el mundo imperial persa que estos libros habitan. En Ester, ''Susa la ciudadela'' (שׁוּשַׁן הַבִּירָה) distingue la fortaleza-palacio real de la ciudad más amplia de Susa (compárese Est 3:15 y 8:14-15, donde se mencionan tanto la ciudadela como la ciudad). En Crónicas designa el complejo del templo de Jerusalén como un recinto real-sagrado (1 Cr 29:1, 19). La Septuaginta griega lo traduce como βᾶρις, la misma palabra que Josefo usa para la fortaleza conocida después como la Antonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1004a', 'spa', 'entre (variante rara de בֵּין); preposición que indica posición intermedia', 'Forma femenina poco frecuente de la preposición «entre» (בֵּין/בֵּן), atestiguada solo en unos pocos pasajes poéticos o textualmente inciertos. Las lecturas propuestas incluyen Ezequiel 41:9 (arquitectura del templo), Proverbios 8:2 (la Sabiduría en las encrucijadas) y Job 8:17 (raíces entrelazadas). Versiones antiguas como la Septuaginta, el Targum y la Vulgata a veces respaldan esta lectura como «en medio de» o «entre», aunque algunos eruditos modernos prefieren enmendar al estándar בֵּין. La forma ilustra variación dialectal o poética en las preposiciones hebreas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1004b', 'spa', 'Casa, vivienda, edificio; por extensión: familia, linaje, dinastía; espacialmente: adentro, interior; también: templo.', 'בַּיִת es uno de los sustantivos más frecuentes y versátiles de la Biblia hebrea, y ancla toda una red de significados en torno al concepto de espacio habitable cerrado. En su sentido más concreto designa cualquier estructura física — una casa, un palacio, una cárcel, un almacén — y aparece en cadenas constructas con tanta frecuencia (''casa de Dios'', ''casa del rey'', ''casa de Israel'') que funciona casi como una partícula relacional. Pero su alcance semántico va mucho más allá de la arquitectura: ''casa de David'' significa la dinastía davídica, ''casa de Israel'' puede referirse a la nación como familia, y con sufijos direccionales בַּיִת se convierte en ''adentro'' o ''por dentro'', perdiendo toda referencia edilicia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1005', 'spa', 'Casa, templo — un edificio o morada; especialmente la casa de Dios (el templo de Jerusalén) en las porciones arameas', 'Casa, templo — un edificio o morada; especialmente la casa de Dios (el templo de Jerusalén) en las porciones arameas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1007', 'spa', 'Bet-Avén; topónimo que significa ''casa de iniquidad'', al este de Betel, usado también como apodo despectivo de Betel.', 'Nombre de lugar que significa ''casa de iniquidad'' o ''casa de maldad'', designando una localidad al este de Betel. En los libros históricos aparece como un topónimo genuino cerca de Hai y Betel (Jos 7:2; 18:12; 1 Sam 13:5; 14:23). Sin embargo, en Oseas adquiere un filo profético mordaz: el profeta parece emplear ''Bet-Avén'' (casa de maldad) como un juego de palabras deliberado con ''Betel'' (casa de Dios), condenando la idolatría del santuario del norte (Os 4:15; 5:8; 10:5). Este doble uso lo convierte tanto en un lugar real como en un juicio teológico condensado en un solo nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1008', 'spa', 'Betel — ''casa de Dios''; antigua ciudad cananea en Efraín, importante centro de culto israelita vinculado a la visión de Jacob.', 'Betel — ''casa de Dios''; antigua ciudad cananea en Efraín, importante centro de culto israelita vinculado a la visión de Jacob.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1019', 'spa', 'Gilgal, círculo sagrado de piedras; primer campamento de Israel en Canaán y posterior sitio de culto ilícito', 'Varios lugares llevaban este nombre, pero el más significativo fue el primer campamento de Israel al oeste del Jordán, donde Josué erigió doce piedras y el pueblo fue circuncidado. Se convirtió en punto de reunión para consejos de guerra y en parada habitual del circuito judicial de Samuel. Sin embargo, este mismo sitio terminó albergando cultos ilegítimos que los profetas condenaron duramente: Oseas y Amós denunciaron sus rituales corrompidos. La conexión del nombre con «quitar rodando» el oprobio de Egipto creó un poderoso juego de palabras en Josué. Gilgal encarnó así tanto la renovación como el fracaso del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1020', 'spa', 'Bet-Jesimot — ciudad al este del Jordán en territorio de Moab/Rubén, cerca del mar Muerto', 'Nombre de lugar que significa «casa de los páramos», designando una ciudad al este del río Jordán en la llanura moabita, cerca del extremo norte del mar Muerto. Israel acampó allí al final de la travesía por el desierto (Nm 33:49), y aparece entre los límites territoriales del reino amorreo (Jos 12:3) y en la herencia tribal de Rubén (Jos 13:20). Ezequiel 25:9 la menciona entre «la gloria de la tierra» que sería expuesta a los invasores. Comúnmente se identifica con la moderna es-Suweimeh.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1022', 'spa', 'Betlemita — gentilicio de Belén, que identifica a alguien como oriundo de esa ciudad', 'Adjetivo gentilicio que identifica a una persona como procedente de Belén. Aparece exclusivamente en las narrativas del ascenso de David: Isaí es llamado «el betlemita» cuando Samuel es enviado a ungir a uno de sus hijos (1 S 16:1, 18), David se identifica con esta designación ante Saúl (1 S 17:58), y el guerrero Eljanán es descrito como betlemita (2 S 21:19). El término posee un sutil peso literario, vinculando los humildes orígenes de David con la ciudad que se convertiría en sinónimo de esperanza mesiánica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1026', 'spa', 'Bet-Arabá, topónimo que significa «casa de la Arabá»; ciudad fronteriza entre Judá y Benjamín', 'Nombre de lugar que significa «casa/lugar de la Arabá», en referencia al valle desértico del Rift. La ciudad aparece en las descripciones de los límites tribales: asignada a Judá (Josué 15:6, 61) y también a Benjamín (Josué 18:22), lo cual probablemente indica un ajuste fronterizo o una doble referencia. El nombre también se abrevia como «la Arabá» o con sufijo direccional «hacia la Arabá» (Josué 18:18). Su ubicación exacta es desconocida, pero se hallaba en algún punto a lo largo de la frontera entre Judá y Benjamín, en la zona desértica que desciende hacia el Mar Muerto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1031', 'spa', 'Bet-hoglá, nombre de ciudad que significa ''casa de la perdiz''; en la frontera entre Judá y Benjamín', 'Nombre de lugar que significa ''casa/lugar de la perdiz'', situado en el límite entre los territorios de Judá y Benjamín. Aparece en las asignaciones territoriales de Josué: la frontera entre Judá y Benjamín pasa por Bet-hoglá (Josué 15:6; 18:19), y la ciudad se incluye en la herencia de Benjamín (Josué 18:21). Se identifica con la actual Ain Hajla (o Qasr Hajla), que conserva el nombre antiguo. La referencia a la perdiz podría indicar que la zona era conocida por estas aves o que llevaba el nombre de algún rasgo natural del lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1032', 'spa', 'Bet-horón -- par de ciudades (Alta y Baja) en Efraín sobre un paso montañoso estratégico', 'Bet-horón -- par de ciudades (Alta y Baja) en Efraín sobre un paso montañoso estratégico');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1035', 'spa', 'Belén — ciudad de Judá al sur de Jerusalén, cuna de David, cuyo nombre significa ''casa del pan''', 'Belén — ciudad de Judá al sur de Jerusalén, cuna de David, cuyo nombre significa ''casa del pan''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1037', 'spa', 'Milo, terraplén o terraza en Jerusalén; posiblemente un área rellenada o estructura de fortaleza', 'Este elemento arquitectónico de Jerusalén aparece vinculado a los proyectos de construcción de David y Salomón, y designa ya sea una terraza, un baluarte o una fortificación de relleno. El término podría describir una estructura específica dentro de la ciudad de David, quizás terrazas de contención en las empinadas laderas o una ciudadela. Joás fue asesinado en «Bet-milo» o «la casa de Milo», lo que sugiere funciones residenciales o administrativas. La raíz de la palabra, que significa «rellenar», ha dado lugar a diversas interpretaciones: un barranco rellenado, una plataforma elevada o una fortificación de tierra. Los restos arqueológicos muestran extensos sistemas de terrazas en la antigua Jerusalén que podrían corresponder a esta estructura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1040', 'spa', 'Bet-edén, ciudad o región aramea; posible nombre bíblico de Bit-Adini en Mesopotamia', 'Amós pronuncia juicio contra esta localidad aramea, probablemente la región conocida en los registros asirios como Bit-Adini, a orillas del Éufrates. El nombre significa «casa de Edén» o «casa de deleite», y posiblemente conserva un topónimo antiguo relacionado con la palabra para placer. La tradición posterior a veces lo identificó con «los hijos de Edén» mencionados en Isaías y Reyes. La identificación geográfica sigue siendo algo incierta, aunque la conexión mesopotámica parece la más probable. El oráculo de Amós lo sitúa entre los territorios aliados de Damasco sujetos al juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1043', 'spa', 'Bet-anat, ciudad en Neftalí que significa ''casa/templo de Anat'' (diosa cananea); enclave cananeo no conquistado', 'Ciudad en el territorio de Neftalí cuyo nombre significa ''casa/templo de Anat'', una diosa cananea. Aparece en la asignación territorial de Josué a Neftalí (Josué 19:38) y en la lista de Jueces de ciudades cananeas no conquistadas, cuyos habitantes fueron sometidos a trabajos forzados en lugar de ser expulsados (Jueces 1:33). El elemento teofórico del nombre (Anat) sugiere que originalmente fue un centro de culto cananeo. El fracaso de Israel en desposeer completamente a Bet-anat refleja el tema de la conquista incompleta en Jueces. Posible ubicación moderna: Ain-Atha o Ainítha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1044', 'spa', 'Bet-eqed, ''casa de atadura de los pastores''; lugar donde Jehú mató a los parientes de Ocozías', 'Nombre de lugar que significa ''casa de atadura de los pastores'', que aparece únicamente en el relato de la purga de Jehú contra la casa de Acab. Jehú encontró a parientes del rey Ocozías de Judá ''en Bet-eqed de los pastores'' y los masacró en ''el pozo de Bet-eqed'' (2 Reyes 10:12, 14). El nombre podría referirse a una instalación para el esquileo de ovejas o a un lugar de reunión de pastores. La ubicación exacta es incierta; se ha propuesto Beit Kad, cerca del monte Gilboa. La doble mención (vv. 12, 14) enfatiza la importancia del sitio como escenario de la matanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1045', 'spa', 'Astoret, diosa cananea; deidad astral de la fertilidad cuyo culto Israel adoptó repetidamente', 'Esta diosa cananea, conocida en otras culturas como Astarté o Ishtar, representaba la fertilidad, el amor y la guerra. Israel cayó repetidamente en su culto, erigiendo imágenes y lugares altos a pesar de las prohibiciones del pacto. La vocalización bíblica probablemente distorsiona el nombre de forma deliberada, insertando las vocales de la palabra «vergüenza» como expresión de desprecio. Salomón edificó lugares altos para ella durante su apostasía; Josías los destruyó después. La forma plural aparece con frecuencia, indicando quizá múltiples manifestaciones locales o imágenes. Su culto incluía prostitución ritual y prácticas que los profetas condenaron como adulterio espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1046', 'spa', 'Bet-pelet, ciudad en el sur de Judá que significa ''casa de escape/refugio''; repoblada tras el exilio', 'Nombre de ciudad que significa ''casa/lugar de escape'', ubicada en el territorio meridional de Judá. Aparece en la lista de ciudades del Neguev de Judá (Josué 15:27) y en el registro de Nehemías sobre la repoblación tras el exilio (Nehemías 11:26). La raíz del nombre sugiere liberación o refugio. Su mención en las listas postexílicas indica que fue repoblada por los judíos que regresaron de Babilonia. El gentilicio ''paltita'' (2 Samuel 23:26; 1 Crónicas 11:27; 27:10) podría estar relacionado con esta ciudad, aunque existen variantes textuales. Su ubicación exacta es desconocida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1047', 'spa', 'Bet-peor — lugar al este del Jordán en Moab, vinculado al sitio de culto de Baal-peor', 'Nombre de lugar que significa ''casa de Peor,'' designando una localidad en Moab al este del Jordán donde Israel recibió las últimas instrucciones de Moisés. Está estrechamente asociado con el infame incidente de Baal-peor, aunque Bet-peor aparece en contextos geográficos más que cultuales: Moisés se dirigió a Israel en el valle frente a Bet-peor (Dt 3:29; 4:46), fue sepultado en sus cercanías (Dt 34:6), y la ciudad fue asignada a la tribu de Rubén (Jos 13:20). El nombre evoca tanto la gravedad de la apostasía anterior de Israel como la solemnidad de las últimas palabras de Moisés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1049', 'spa', 'Bet-sur — ciudad fortificada en la serranía de Judá, al sur de Jerusalén', 'Nombre de lugar que significa ''casa de roca,'' identificando una ciudad fortificada en la zona montañosa de Judá, a unos veinte kilómetros al sur de Jerusalén. Aparece en la asignación territorial de Judá (Jos 15:58), fue fortificada por Roboam como bastión defensivo (2 Cr 11:7) y su jefe de distrito colaboró en la reconstrucción de los muros de Jerusalén bajo Nehemías (Neh 3:16). En 1 Crónicas 2:45 el nombre aparece como nombre personal en una genealogía calebita, probablemente reflejando al fundador epónimo del asentamiento. El sitio moderno es Khirbet et-Tubeiqeh.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1050', 'spa', 'Bet-rejob, ciudad/región en el extremo norte cerca de Dan; aliada con Amón contra Israel', 'Nombre de lugar en la frontera septentrional, cerca de Dan y en el camino hacia Hamat. Cuando los danitas buscaron conquistar Lais, la ciudad no tenía aliados porque estaba ''lejos de Sidón'' y ''cerca de Bet-rejob'' (Jueces 18:28). Durante la guerra de David contra Amón, los arameos de Bet-rejob proporcionaron mercenarios para combatir a Israel (2 Samuel 10:6). Bet-rejob parece ser idéntica a ''Rejob'' en Números 13:21 y 2 Samuel 10:8. El nombre significa ''casa de la plaza/lugar amplio''. Su ubicación es incierta, pero probablemente se hallaba en el valle de la Becá o en la región del alto Jordán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1052', 'spa', 'Bet-Seán, ciudad fortificada en el territorio de Manasés, en el valle de Jezreel, al oeste del Jordán.', 'Nombre propio de lugar que significa «casa de reposo» o «casa de seguridad», designando una ciudad importante en la confluencia de los valles de Jezreel y del Jordán. Bet-Seán fue asignada a Manasés, pero nunca fue conquistada del todo (Jos 17:11, 16; Jue 1:27). Se hizo tristemente célebre como el sitio donde los filisteos colgaron los cuerpos de Saúl y sus hijos en la muralla (1 Sam 31:10, 12; 2 Sam 21:12). Salomón la convirtió después en centro administrativo (1 Re 4:12). Las traducciones interlingüísticas son notablemente uniformes, conservando el nombre compuesto en todos los idiomas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1053', 'spa', 'Bet-Semes (''casa del sol''); ciudad levítica en Judá, también nombres de lugares en Neftalí e Isacar', 'Bet-Semes (''casa del sol''); ciudad levítica en Judá, también nombres de lugares en Neftalí e Isacar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1055', 'spa', 'pabellón, estructura ajardinada del palacio (préstamo persa); edificio real de jardín', 'Préstamo del persa que designa un pabellón de jardín o estructura palaciega, presente únicamente en el libro de Ester. El palacio de Susa tenía «el jardín del pabellón del palacio», donde Asuero celebró su gran banquete (Ester 1:5) y donde se desarrolla la escena decisiva de Ester 7: el rey sale airado al «jardín del palacio» y al regresar encuentra a Amán postrado sobre el lecho de Ester (Ester 7:7-8). El término podría estar emparentado con «apadana» (salón del trono) y evoca el escenario opulento de la corte persa central en la narrativa de Ester.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1057', 'spa', 'Árbol de bálsamo; árbol (posiblemente resinoso o llorón) en cuyos bosquecillos Dios dirigió la estrategia militar de Israel', 'Designa una especie arbórea específica, probablemente el bálsamo o la morera, identificada por su savia resinosa que gotea. El nombre puede derivar de una raíz que significa ''llorar'' o ''gotear.'' En 2 Samuel 5:23-24 y 1 Crónicas 14:14-15, Dios instruye a David a rodear a los filisteos por detrás a través de la arboleda de bálsamos y esperar el sonido de pasos en las copas como señal divina para atacar. El Salmo 84:7 habla de pasar por el ''Valle de Bacá,'' imagen poética de transformar un lugar árido y de llanto en un manantial de bendición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1058', 'spa', 'Llorar, lamentarse en voz alta; en Piel, plañir o hacer duelo por alguien con lamento intensificado', 'בָּכָה es el verbo hebreo primario para el llanto, y aparece más de cien veces en todos los registros emocionales: el dolor por la pérdida (Gn 37:35), la alegría del reencuentro (Gn 33:4), la intercesión ante Dios (2 R 20:3) y el duelo comunitario (Jue 20:23). Corresponde al árabe بَكَى y al arameo בְּכָא, reflejando una raíz pansemítica. La intensificación Piel concentra el enfoque en la lamentación dirigida a otro o en nombre de otro, como cuando Raquel «llora por sus hijos» (Jer 31:15), pasaje retomado después en el relato de la infancia de Mateo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1060', 'spa', 'Primogénito: el primer hijo o descendiente, con derechos especiales de herencia; figuradamente, preeminencia o primacía', 'בְּכוֹר designa al primer descendiente que abre la matriz, sea humano o animal, y tiene enorme peso legal y teológico en la Biblia hebrea. El hijo primogénito recibía doble porción de la herencia (Dt 21:17) y ocupaba un puesto de honor en la familia. La reclamación de Dios sobre todo primogénito —establecida en el éxodo cuando los primogénitos de Egipto fueron heridos (Éx 12:29; 13:2)— se convirtió en la base de la sustitución levítica y la redención de los primogénitos (Nm 3:12-13; 18:15-16). En sentido figurado, בְּכוֹר expresa preeminencia: Israel es el «hijo primogénito» de Dios (Éx 4:22), y Job 18:13 habla estremecedoramente del «primogénito de la muerte».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1061', 'spa', 'Se refiere a los primeros productos agrícolas que maduran en cada temporada, apartados como sagrados para Dios dentro del calendario cultual de Israel', 'Se refiere a los primeros productos agrícolas que maduran en cada temporada, apartados como sagrados para Dios dentro del calendario cultual de Israel. El término ancla festivales importantes: el pan de las primicias en Pentecostés (Lv 23:20) y el ''día de las primicias'' (Nm 28:26). En un uso secundario más concreto, describe higos de maduración temprana — Nahúm 3:12 compara las fortalezas de Nínive con higueras cuyo primer fruto maduro cae con solo sacudirlas, y los espías trajeron de vuelta productos tempranos de la tierra prometida (Nm 13:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1062', 'spa', 'Primogenitura o condición de primogénito; también primicias del ganado ofrecidas a Dios', 'Primogenitura o condición de primogénito; también primicias del ganado ofrecidas a Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1065', 'spa', 'Llanto; el acto o sonido de llorar por dolor, duelo, arrepentimiento o súplica', 'Llanto; el acto o sonido de llorar por dolor, duelo, arrepentimiento o súplica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1067', 'spa', 'bekhirah — la hija primogénita, la mayor de dos hermanas o hijas', 'El sustantivo femenino bekhirah designa a la hija primogénita, la mayor de un par de hermanas. Aparece exclusivamente en contextos narrativos donde el orden de nacimiento determina la precedencia social: la hija mayor de Lot toma la iniciativa para preservar el linaje familiar (Gen 19:31-37), y Labán invoca la costumbre para justificar entregar a Lea antes que a Raquel (Gen 29:26). La hija primogénita de Saúl, Merab, se distingue de manera similar (1 Sam 14:49). Todas las evidencias interlingüísticas confirman un significado único y estable vinculado a la prioridad femenina por orden de nacimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1069', 'spa', 'Dar fruto temprano; tratar o designar como primogénito; estar en los dolores de un primer parto', 'Abarca un campo semántico que va desde la precocidad agrícola hasta las dimensiones legales y físicas de la primogenitura. En el Piel, significa dar fruto temprano o primerizo (Ez 47:12) o conferir los derechos de primogénito a un hijo (Dt 21:16). El Pual indica ser nacido o designado como primogénito (Lv 27:26), mientras que el participio Hifil en Jeremías 4:31 describe vívidamente a una mujer dando a luz a su primer hijo. El cognado árabe بَكَرَ (''madrugar, hacer algo temprano'') ilumina la noción central de primacía y anterioridad que unifica estos usos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1071', 'spa', 'Béquer: nombre propio que significa ''camello joven'', llevado por un hijo de Benjamín y un hijo de Efraín.', 'Béquer es un nombre personal hebreo derivado de una raíz que significa ''camello joven'' (cf. árabe bakr). Lo llevan dos personajes distintos en las Escrituras: un hijo de Benjamín mencionado en las genealogías de Génesis 46:21 y 1 Crónicas 7:6, 8, y un hijo de Efraín en Números 26:35, donde la variante Bered aparece en 1 Crónicas 7:20. El cognado asirio bakru confirma la raíz semántica de ''primogénito'' o ''joven'' que subyace al nombre. Las traducciones al español lo recogen habitualmente como ''Béquer''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1075', 'spa', 'Bicri — benjaminita, padre de Seba, el rebelde que encabezó una insurrección contra David.', 'Nombre propio masculino que identifica a un antepasado benjaminita, conocido exclusivamente como el padre de Seba ben Bicri, el hombre que levantó una revuelta contra el rey David después de la rebelión de Absalón (2 Sam 20). El nombre puede significar «juvenil» (de bekor, «primogénito»). Las ocho apariciones se dan en la frase patronímica fija «Seba hijo de Bicri», y el nombre se traduce de forma bastante uniforme en las distintas lenguas: Bichri en inglés y francés, Bejri en español, Bichri en alemán, lo que refleja una tradición de transliteración estable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1077', 'spa', 'No — partícula poética y arcaica de negación, sinónima de לֹא pero usada casi exclusivamente en verso elevado.', 'No — partícula poética y arcaica de negación, sinónima de לֹא pero usada casi exclusivamente en verso elevado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1078', 'spa', 'Bel, deidad principal de Babilonia identificada con Marduk; dios babilónico vencido en los oráculos proféticos', 'El dios babilónico Bel (que significa «señor»), identificado con Marduk, deidad patrona de Babilonia. Los oráculos proféticos ridiculizan su impotencia: «Se ha inclinado Bel, se ha abatido Nebo» (Isaías 46:1), mientras sus ídolos son cargados en bestias: dioses incapaces de salvarse a sí mismos. Jeremías proclama la caída de Babilonia: «Bel es avergonzado, Merodac es quebrantado» (Jeremías 50:2) y «Castigaré a Bel en Babilonia» (Jeremías 51:44). La polémica profética contra los ídolos apunta al dios principal de Babilonia como símbolo del orgullo imperial destinado a la humillación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1082', 'spa', 'Brillar, alegrarse, sonreír; causar un destello de destrucción sobre el fuerte', 'Verbo raro que solo aparece en Hifil, portando tanto la calidez de un rostro iluminado como la violencia de un destello repentino de ruina. En Job 9:27 y 10:20, Job resuelve dejar de lado su queja y ''alegrarse'' o ''mostrar una sonrisa,'' un acto de ánimo forzado ante el sufrimiento. El Salmo 39:13 emplea el mismo giro como súplica: ''Aparta de mí tu mirada, para que pueda sonreír de nuevo.'' Pero Amós 5:9 torna la palabra ominosa: Dios ''hace brillar la destrucción sobre la fortaleza,'' convirtiendo ese mismo resplandor en instrumento de juicio. El cognado árabe بَلِجَ (''brillar, ser radiante'') confirma la imagen raíz de un brillo súbito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1083', 'spa', 'Bilga, nombre propio que significa «alegría»; nombre de familia sacerdotal en tiempos de David y del posexilio', 'Nombre propio de familias sacerdotales, cuyo significado probable es «alegría» o «resplandor». Un Bilga encabezó la decimoquinta división sacerdotal en la organización del servicio del templo establecida por David (1 Crónicas 24:14). Un sacerdote llamado Bilga regresó del exilio con Zorobabel (Nehemías 12:5), y una generación posterior de la misma familia firmó el pacto de Nehemías (Nehemías 12:18). El nombre aparece en genealogías sacerdotales que vinculan el culto del templo preexílico con la comunidad restaurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1085', 'spa', 'Bildad: uno de los tres amigos de Job, llamado ''el suhita'', que sostiene que el sufrimiento implica culpa.', 'Bildad el suhita es uno de los tres compañeros que acuden a consolar a Job en su aflicción. Su nombre probablemente significa ''Bel ha amado'', lo que lo vincula a patrones teofóricos del antiguo Oriente Próximo (cf. Eldad). Interviene en tres ciclos de discursos (Job 8, 18, 25), defendiendo de manera constante el principio de retribución: Dios no pervierte la justicia y los malvados inevitablemente perecen. Todas las traducciones principales conservan el nombre sin alteración, lo que refleja su arraigo firme en la tradición bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1086', 'spa', 'Este verbo comienza con la imagen de una tela que se deshilacha y se deshace. Moisés le recuerda dos veces a Israel que sus vestiduras no se ''gastaron', 'Este verbo comienza con la imagen de una tela que se deshilacha y se deshace. Moisés le recuerda dos veces a Israel que sus vestiduras no se ''gastaron'' durante cuarenta años de peregrinación por el desierto (Dt 8:4; 29:5), y los gabaonitas exhiben ropas gastadas como prueba engañosa de un largo viaje (Jos 9:13). De la tela raída, la palabra se expande a escala cósmica: los cielos se ''gastarán como un vestido'' (Sal 102:26; Is 51:6). El Piel intensifica la acción — Dios ''consume'' la carne y la piel (Lm 3:4) — pero luego da un giro positivo sorprendente en Job 21:13 e Isaías 65:22, donde los malvados o los bendecidos ''pasan'' sus días plenamente, disfrutándolos hasta el final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1087', 'spa', 'Gastado, viejo, deteriorado; dicho de vestiduras, sacos, odres, sandalias, y figuradamente de una mujer agotada.', 'Este adjetivo describe algo que ha sido usado hasta el punto de deteriorarse por completo. En Josue 9:4-5, los gabaonitas llevan deliberadamente sacos gastados, odres rotos, sandalias remendadas y vestiduras viejas para enganar a Israel haciendoles creer que venian de muy lejos. En Ezequiel 23:43 se aplica figuradamente a una mujer consumida por el adulterio. El espectro semantico abarca desde el desgaste fisico de objetos materiales hasta la degradacion moral de una persona, reflejando la versatilidad del termino hebreo que cubre tanto lo literal como lo metaforico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1090a', 'spa', 'Bilha — nombre propio: sierva de Raquel dada a Jacob, madre de Dan y Neftalí. Bilha (בִּלְהָה) es un nombre personal que identifica a la sierva de Raq', 'Bilha — nombre propio: sierva de Raquel dada a Jacob, madre de Dan y Neftalí. Bilha (בִּלְהָה) es un nombre personal que identifica a la sierva de Raquel, quien fue entregada a Jacob como esposa sustituta cuando Raquel resultó estéril. A través de Bilha, Jacob engendró a Dan y Neftalí, dos de las doce tribus de Israel (Gn 30:3-8). Aparece por primera vez cuando Labán la entrega a Raquel en el matrimonio (Gn 29:29) y reaparece en la inquietante noticia de que Rubén se acostó con ella, acto que le costó su primogenitura (Gn 35:22; 49:4; 1 Cr 5:1). Otra Bilha aparece como ciudad simeonita (1 Cr 4:29). La etimología podría relacionarse con la raíz b-l-h, sugiriendo ''timidez'' o ''temblor'', aunque esto sigue siendo incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1091', 'spa', 'Terror, calamidad repentina — pavor extremo o destrucción abrumadora que sobreviene a los malvados o a los afligidos. El sustantivo femenino בַּלָּהָה', 'Terror, calamidad repentina — pavor extremo o destrucción abrumadora que sobreviene a los malvados o a los afligidos. El sustantivo femenino בַּלָּהָה (ballahah) expresa un espanto intenso, destrucción súbita o calamidad sobrecogedora. Sus diez apariciones se concentran en la literatura sapiencial y profética, predominantemente en Job, con apariciones adicionales en los Salmos y Ezequiel. En Job 18:11-14, los terrores acosan al malvado por todos lados y lo conducen ante el ''rey de los espantos'' (la muerte personificada). Job 24:17 identifica las tinieblas profundas con los terrores. Ezequiel emplea el término para la aniquilación que aguarda a Tiro y Sidón (Ez 26:21; 27:36; 28:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1092', 'spa', 'Bilhán; nombre propio de un descendiente de Esaú (horita) y de un jefe de clan benjamita.', 'Nombre propio que aparece en las listas genealógicas del Antiguo Testamento. El primer Bilhán es un horita, descendiente de Esaú, mencionado entre los jefes de clan de Seír en Génesis 36:27 y 1 Crónicas 1:42, lo que lo sitúa dentro de la población preisraelita de Edom. El segundo Bilhán es hijo de Jediael, de la tribu de Benjamín (1 Cr 7:10), un líder militar cuya familia contaba con miles de guerreros. El nombre se transliteraיconsistentemente en todas las tradiciones lingüísticas, sin variantes etimológicas significativas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1093', 'spa', 'tributo, impuesto (préstamo arameo/persa); gravamen imperial sobre las provincias', 'Préstamo del arameo o del persa que designa un tributo o impuesto, presente exclusivamente en los relatos de Esdras sobre la administración persa. El término aparece en listas formularias de gravámenes imperiales: «tributo, contribución y peaje» (Esdras 4:13, 20; 7:24). Los opositores a la reconstrucción de Jerusalén advierten que, si la ciudad es restaurada, dejará de pagar estos impuestos al rey. El decreto de Artajerjes exime al personal del templo de «tributo, contribución o peaje». La palabra refleja el vocabulario burocrático de la recaudación fiscal persa en las provincias occidentales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1094', 'spa', 'harapos, ropa vieja y raída; prendas gastadas usadas como acolchado o atadura', 'Ropa gastada o harapos, mencionados únicamente en el relato de Jeremías sobre el rescate del profeta de una cisterna. Ebed-melec recoge «trapos viejos y harapos» del almacén del palacio y los hace descender a Jeremías para que se los coloque bajo las axilas como protección antes de ser izado con cuerdas (Jeremías 38:11-12). El término designa tela demasiado deteriorada para uso normal, pero aún útil como acolchado. La repetición de «gastado» tres veces subraya la compasión improvisada hacia el profeta encarcelado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1096', 'spa', 'Beltsasar — nombre babilónico de corte asignado al profeta Daniel.', 'Nombre babilónico asignado a Daniel por el jefe de los oficiales de Nabucodonosor (Dan 1:7), usado a lo largo de las secciones arameas de Daniel cuando el rey o los cortesanos se dirigen a él. El nombre probablemente proviene del acadio Balat-su-usur («protege su vida») y sirvió para integrar a Daniel en la cultura de la corte babilónica. El español Beltsasar y el alemán Belsazar reflejan la tradición de la Septuaginta (Baltasar), mientras que el inglés Belteshazzar conserva una aproximación más fiel a la forma aramea. Las ocho apariciones se encuentran en Daniel 2–5, siempre en contextos de audiencia real e interpretación de sueños.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1097', 'spa', 'Sin, no, por falta de; raramente como sustantivo: nada, destrucción.', 'Sin, no, por falta de; raramente como sustantivo: nada, destrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1098', 'spa', 'Forraje, mezcla de grano y heno para alimentar al ganado; pienso preparado para animales de labor', 'Forraje o pienso mezclado para animales, una combinación de grano y hierba seca. Job emplea el término dos veces en preguntas retóricas: ''¿Rebuzna el asno montés junto a su hierba? ¿Muge el buey junto a su forraje?'' (Job 6:5), sugiriendo que quejarse sin causa es antinatural. Más adelante, ''recogen su forraje en el campo'' (Job 24:6) describe a los pobres rebuscando alimento para animales. Isaías profetiza abundancia: los bueyes y asnos comerán ''forraje sazonado'' (Isaías 30:24), indicando pienso de alta calidad. Los cognados arameos y árabes confirman el sentido de alimento húmedo y mezclado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1100', 'spa', 'Inutilidad, maldad — sustantivo abstracto para la vileza moral, frecuentemente en la expresión ''hijos de Belial''; también usado como imagen casi mític', 'Inutilidad, maldad — sustantivo abstracto para la vileza moral, frecuentemente en la expresión ''hijos de Belial''; también usado como imagen casi mítica de destrucción');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1101a', 'spa', 'Mezclar o entremezclar; predominantemente término cúltico para ofrendas de grano mezcladas con aceite, pero también confundir el lenguaje y mezclarse ', 'Mezclar o entremezclar; predominantemente término cúltico para ofrendas de grano mezcladas con aceite, pero también confundir el lenguaje y mezclarse entre naciones');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1104', 'spa', 'Tragar, engullir; devorar, envolver; destruir; pasivo: ser tragado; también: confundir, desconcertar.', 'Tragar, engullir; devorar, envolver; destruir; pasivo: ser tragado; también: confundir, desconcertar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1106a', 'spa', 'Bela — nombre propio de un antiguo rey de Edom y de un hijo de Benjamín', 'Bela (בֶּלַע) es un nombre propio hebreo que significa ''destrucción'' o ''deglución'', derivado de la raíz בָּלַע (''tragar''). Lo llevan al menos dos personajes distintos en el Antiguo Testamento. El primero es Bela hijo de Beor, el primer rey nombrado de Edom, que reinó en la ciudad de Dinaba antes de que hubiera rey en Israel (Gn 36:32–33; 1 Cr 1:43–44). El segundo es Bela hijo de Benjamín, nieto de Jacob, incluido entre quienes descendieron a Egipto (Gn 46:21; Nm 26:38, 40; 1 Cr 7:6–7; 8:1, 3). La ciudad de Bela se identifica también con Zoar en Génesis 14:2, 8. En cada lengua receptora se conserva el nombre con mínima adaptación fonológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1107', 'spa', 'Preposición compuesta construida a partir de bal (''no'') y ''ad/adê (''hasta''), que produce el sentido ''no hasta'' y por tanto ''aparte de, además de, sin''', 'Preposición compuesta construida a partir de bal (''no'') y ''ad/adê (''hasta''), que produce el sentido ''no hasta'' y por tanto ''aparte de, además de, sin''. Frecuentemente toma sufijos pronominales: bil''adai (''aparte de mí'', Is 45:6), bal''adekha (''sin ti'', Gn 41:44). En Génesis 14:24, Abraham la usa como partícula deprecatoria — ''¡no para mí!'' — rechazando cualquier parte personal del botín de guerra. El cognado siríaco belad tiene el mismo significado (''sin, aparte de''), confirmando las profundas raíces semíticas del compuesto. La palabra aparece tanto en contextos legal-narrativos como profético-teológicos, afirmando a menudo la exclusividad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1109a', 'spa', 'Balaam — profeta-adivino mesopotámico contratado para maldecir a Israel pero obligado a bendecirlo.', 'Balaam — profeta-adivino mesopotámico contratado para maldecir a Israel pero obligado a bendecirlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1111', 'spa', 'Balac — rey de Moab que contrató a Balaam para maldecir a Israel durante el período del desierto', 'Balac — rey de Moab que contrató a Balaam para maldecir a Israel durante el período del desierto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1113', 'spa', 'Belsasar; último rey de Babilonia en el libro de Daniel, quien vio la escritura en la pared durante su último banquete.', 'Nombre propio arameo de Belsasar (בֵּלְשַׁאצַּר), el rey babilónico protagonista de Daniel 5 y mencionado en Daniel 7:1 y 8:1. Es el gobernante que celebró el célebre banquete durante el cual una mano misteriosa escribió en la pared, proclamando la caída de su reino (Dan 5:1-30). Históricamente hijo de Nabónido y corregente de Babilonia, su nombre significa ''Bel, protege al rey'' en acadio. El relato de su festín y su caída se ha convertido en una de las escenas más emblemáticas de la literatura bíblica, dando origen a la expresión proverbial ''la escritura en la pared''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1115', 'spa', 'Partícula de negación: «no, para que no, excepto, sin»; de una raíz que significa «cesar», usada para propósito negativo, exclusión y privación', 'Derivada de la raíz בָּלָה («desgastarse, cesar»), בִּלְתִּי expresa la idea de cesación o inexistencia desplegada como partícula gramatical. Su uso más frecuente (84 de 112 ocurrencias) es con la preposición lamed para formar cláusulas de propósito negativo —«para que no»—, como cuando Dios marca a Caín para que nadie lo mate (Gn 4:15). También funciona como partícula exceptiva («excepto, a menos que») y puede expresar ausencia pura («sin»). El español «para no» logra captar con elegante brevedad este compacto negador hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1116', 'spa', 'Lugar alto: sitio elevado de culto (a menudo santuarios ilícitos) o elevación geográfica, cresta o altura montañosa', 'En el antiguo Israel, una בָּמָה era una plataforma elevada al aire libre utilizada para sacrificios y adoración. Si bien algunos lugares altos sirvieron para culto legítimo antes de la construcción del templo (1 R 3:2), la mayoría de las referencias conllevan una fuerte connotación negativa como sitios de culto cananeo o israelita no autorizado, condenados reiteradamente por los profetas y los historiadores deuteronomistas. En textos poéticos y proféticos, la palabra conserva su sentido geográfico más antiguo de crestas montañosas o terreno elevado que Dios pisa (Am 4:13; Mi 1:3) o sobre el cual los fieles son hechos caminar (Dt 32:13). El español «lugares altos» y «alturas» preservan la imaginería literal de elevación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1119', 'spa', 'En, con — preposición poética arcaica, forma expandida de beth, usada en verso elevado. La forma בְּמוֹ (bemo) es una expansión arcaica y poética de l', 'En, con — preposición poética arcaica, forma expandida de beth, usada en verso elevado. La forma בְּמוֹ (bemo) es una expansión arcaica y poética de la preposición común beth (''en, con, por''). Aparece exclusivamente en registros poéticos elevados —Job, Salmos, Isaías y posiblemente Deuteronomio 33— funcionando de manera idéntica a la beth estándar con valor locativo (''en''), instrumental (''con'') o direccional (''hacia, a través de''). Job 9:30 habla de lavarse ''con aguas de nieve'', Job 16:4-5 de fortalecer ''con mi boca'', e Isaías 25:10 de Moab siendo pisoteado ''en'' su propio lugar. El sufijo -mo es una partícula enclítica antigua conservada en la poesía arcaica, cognada con expansiones similares en ugarítico y otras lenguas semíticas noroccidentales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1120', 'spa', 'Bamot; ciudad moabita en las alturas, también llamada Bamot-Baal, en la ruta de Israel por el desierto.', 'Topónimo que significa ''lugares altos'', referido a una ciudad en Moab a lo largo del itinerario de los israelitas hacia la Tierra Prometida. Números 21:19-20 la enumera como estación entre Nahaliel y el valle en el campo de Moab. La forma completa Bamot-Baal (''lugares altos de Baal'') en Números 22:41 identifica el sitio cúltico donde Balac llevó a Balaam para divisar y maldecir a Israel, un lugar alto consagrado al culto de Baal. Josué 13:17 la asigna a la tribu de Rubén. Su nombre transparente, derivado de בָּמָה (''lugar alto''), vincula geografía, culto y reivindicaciones territoriales de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1121', 'spa', 'Hijo(s); usado aquí en formas constructas que denotan parentesco, pertenencia o membresía a un grupo o linaje.', 'La palabra hebrea בֵּן (''hijo''), extremadamente común, aparece aquí en un puñado de formas constructas o preposicionales donde indica linaje, pertenencia grupal o relación familiar. En Jueces 20:13, ''hijos de Belial'' designa a hombres perversos entre los benjamitas. En 2 Reyes 19:37 y Daniel 11:10, marca la filiación literal dentro de una sucesión dinástica. En 1 Crónicas 27:12, identifica a un comandante militar por su afiliación tribal o familiar. La flexibilidad semántica de esta palabra, desde la descendencia literal hasta la pertenencia metafórica a una clase, se refleja en todas las lenguas de destino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1121a', 'spa', 'hijo, descendiente varón; miembro de una clase; designación de edad', 'Con casi 5.000 apariciones, la palabra hebrea para ''hijo'' se extiende mucho más allá de la descendencia biológica. Si bien su significado primario es ''hijo varón'', el hebreo emplea la expresión idiomática ''hijo de X'' para indicar ''aquel que se caracteriza por X'' o ''miembro de la categoría X'' — así, ''hijos de los profetas'' son discípulos proféticos, ''hijos de Belial'' son personas despreciables e ''hijos de valor'' son guerreros. La misma construcción con números expresa la edad: ''hijo de treinta años'' significa ''de treinta años de edad''. Esta estructura fraseológica tan productiva revela cómo el hebreo piensa categóricamente a través de metáforas de parentesco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1123', 'spa', 'Hijo (arameo) — equivalente arameo del hebreo בֵּן, usado en Esdras y Daniel para filiación literal y metafórica. El sustantivo arameo בַּר (bar) es e', 'Hijo (arameo) — equivalente arameo del hebreo בֵּן, usado en Esdras y Daniel para filiación literal y metafórica. El sustantivo arameo בַּר (bar) es el cognado del hebreo בֵּן (''hijo'') y aparece en las secciones arameas de Esdras y Daniel. En Esdras funciona en fórmulas genealógicas: ''Zorobabel hijo de Salatiel'' (Esd 5:2), ''Jesúa hijo de Josadac'' (Esd 5:2) y ''los hijos de Israel'' (Esd 6:16). Su aparición más célebre es Daniel 7:13, donde ''uno como un hijo de hombre'' (כְּבַר אֱנָשׁ) se acerca al Anciano de Días, una frase que se convirtió en fundamento de la cristología neotestamentaria. Daniel 6:24 lo usa para los hijos literales arrojados al foso de los leones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1124', 'spa', 'Construir, edificar (Pe''al arameo); ser construido, estar en construcción (Hitpael pasivo)', 'Construir, edificar (Pe''al arameo); ser construido, estar en construcción (Hitpael pasivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1129', 'spa', 'Edificar, construir; Nifal: ser edificado, ser establecido; como participio: constructor; figuradamente, de Dios edificando una mujer, una dinastía o un pueblo', 'בָּנָה es el verbo hebreo estándar para la construcción en todas sus formas: desde Noé edificando un altar tras el diluvio (Gn 8:20) hasta el proyecto del templo de Salomón que define una era. Sin embargo, algunos de sus usos teológicamente más densos son figurados: Dios «edifica» a la mujer de la costilla de Adán (Gn 2:22), «edifica» una dinastía para David (2 S 7:27) y promete «reedificar» a Israel tras el exilio (Jer 31:4). El oído hebreo captaría el juego de palabras entre בָּנָה («edificar») y בֵּן («hijo»), conexión explotada en las narrativas de Raquel y Lea donde tener hijos se describe como ser «edificada» (Gn 16:2; 30:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1130', 'spa', 'Ben-Hadad — nombre dinástico de reyes arameos (sirios) que significa ''hijo del dios Hadad'', portado por al menos tres gobernantes de Damasco', 'Ben-Hadad — nombre dinástico de reyes arameos (sirios) que significa ''hijo del dios Hadad'', portado por al menos tres gobernantes de Damasco');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1131', 'spa', 'Binui — nombre propio postexílico de levitas, exiliados retornados y hombres que repudiaron esposas extranjeras en Esdras-Nehemías.', 'Nombre propio hebreo que significa ''edificado'' (de la raíz בנה, ''edificar''), llevado por al menos cinco individuos en la comunidad postexílica. Un Binui encabezó una familia que regresó con Zorobabel (Neh 7:15), otro fue un levita activo en las reformas de Esdras (Esd 8:33; Neh 10:10; 12:8), y dos más aparecen entre quienes habían tomado esposas extranjeras (Esd 10:30, 38). Las traducciones multilingües transliteran uniformemente el nombre, confirmándolo como una identidad léxica única en todas sus ocurrencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1137', 'spa', 'Bani — nombre hebreo que significa ''edificado'', llevado por múltiples levitas, guerreros y jefes de clan', 'Bani (''edificado'', posiblemente abreviatura de Benayahu, ''el SEÑOR ha edificado'') es un nombre compartido por un notable número de individuos, la mayoría vinculados al servicio levítico o al liderazgo postexílico. Un Bani figuraba entre los guerreros de David, llamado ''el gadita'' (2 S 23:36). Varios levitas de nombre Bani aparecen en contextos postexílicos: leyendo la Ley con Esdras (Neh 8:7), dirigiendo la confesión (Neh 9:4–5) y sellando el pacto (Neh 10:14). Jefes de clan llamados Bani figuran entre quienes tenían esposas extranjeras (Esd 10:29, 34). El francés traduce algunas ocurrencias como ''fils de'', reflejando la confusión con el sustantivo común בֵּן (''hijo'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1138', 'spa', 'Buni, nombre levítico postexílico que posiblemente significa ''edificado''; líder en la época de Nehemías', 'Nombre propio que aparece en las listas de Nehemías, posiblemente con el significado de ''edificado'' o relacionado con ''hijo''. Levitas llamados Buni (o la variante Binúi) participaron en la ceremonia de renovación del pacto (Nehemías 9:4) y firmaron el pacto (Nehemías 10:15). Otro Buni figura como antepasado levítico (Nehemías 11:15), aunque algunos estudiosos proponen leer ''de los hijos de'' en lugar de ''Buni hijo de''. Las variantes textuales y las similitudes entre nombres (Buni, Binúi, Bani) generan incertidumbre sobre si se trata de una o varias personas, pero el nombre pertenece claramente a círculos levíticos y de liderazgo postexílico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1141', 'spa', 'Benaías — nombre propio que significa ''Yah ha edificado'', llevado por el guerrero-capitán de David y varios otros', 'Benaías — nombre propio que significa ''Yah ha edificado'', llevado por el guerrero-capitán de David y varios otros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1144', 'spa', 'Benjamín; hijo menor de Jacob y Raquel, la tribu y el territorio que descienden de él', 'Benjamín significa ''hijo de la mano derecha'', nombre que Jacob dio a su hijo menor para reemplazar la elección de Raquel moribunda, Ben-Oní, ''hijo de mi dolor'' (Gn 35:18). Este cambio de nombre encierra en sí mismo una inversión teológica del duelo al honor. La tribu de Benjamín, aunque la más pequeña (1 S 9:21), produjo al primer rey de Israel, Saúl, y al apóstol Pablo. Su territorio, enclavado entre Judá y Efraín, incluía los accesos septentrionales de Jerusalén, convirtiendo a Benjamín en bisagra perpetua de la geografía política y espiritual de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1145', 'spa', 'Benjaminita — miembro de la tribu de Benjamín, la tribu más pequeña de Israel de la cual surgieron Saúl y otras figuras notables. El gentilicio compue', 'Benjaminita — miembro de la tribu de Benjamín, la tribu más pequeña de Israel de la cual surgieron Saúl y otras figuras notables. El gentilicio compuesto בֶּן־יְמִינִי (ben-yemini) identifica a una persona como perteneciente a la tribu de Benjamín, literalmente ''hijo de la mano derecha'' o ''hijo del sur''. Aparece en momentos narrativos decisivos: Ehúd, el juez zurdo que asesinó al rey moabita Eglón, era benjaminita (Jue 3:15), al igual que el anfitrión del levita en Gabaa (Jue 19:16). Saúl se presenta como ''un benjaminita, de la más pequeña de las tribus de Israel'' (1 Sam 9:21). Simei, quien maldijo a David durante la revuelta de Absalón, es identificado como ''Simei hijo de Gera, benjaminita'' (2 Sam 16:11; 19:16; 1 Re 2:8). La designación porta la compleja reputación de la tribu: guerreros feroces y, sin embargo, casi aniquilados en la guerra civil de Jueces 19-21.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1146', 'spa', 'Edificio o estructura construida, usado exclusivamente en la visión del templo de Ezequiel para muros y edificaciones del santuario.', 'Sustantivo masculino (בִּנְיָן) que significa ''edificio'' o ''estructura'', probablemente un préstamo del arameo. Aparece únicamente en el complejo del templo visionario de Ezequiel (capítulos 40-42), donde designa tanto el muro envolvente del recinto sagrado (Ez 40:5) como la edificación posterior detrás del templo propiamente dicho (Ez 41:12, 15). Su distribución restringida — las siete ocurrencias se concentran en una sola visión profética — lo marca como terminología arquitectónica especializada para describir el espacio sagrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1155', 'spa', 'Uvas verdes o agrias; usado literalmente del fruto inmaduro y proverbialmente de la culpa heredada.', 'Designa uvas que aún no han madurado, ya sea verdes y duras o agrias y astringentes. Isaías 18:5 lo emplea literalmente: Dios cortará los sarmientos cuando el brote se convierta en uva que madura, justo antes de la cosecha. Job 15:33 compara al malvado con una vid que deja caer sus uvas verdes prematuramente. Pero la palabra es más conocida por el proverbio citado en Jeremías 31:29 y Ezequiel 18:2: ''Los padres comieron las uvas agrias, y a los hijos se les destemplaron los dientes'', una queja sobre el castigo heredado que ambos profetas refutan con el principio de responsabilidad individual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1156', 'spa', 'Pedir, solicitar, suplicar o buscar (arameo); en Piel, buscar con diligencia o urgencia. Verbo arameo que se encuentra exclusivamente en Daniel, abarc', 'Pedir, solicitar, suplicar o buscar (arameo); en Piel, buscar con diligencia o urgencia. Verbo arameo que se encuentra exclusivamente en Daniel, abarcando toda la gama de la petición humana, desde solicitudes políticas hasta oración ferviente. Daniel ''pidió'' tiempo al rey Nabucodonosor (Dn 2:16) y luego se volvió a buscar misericordias de Dios (Dn 2:18, 23). La palabra aparece tanto en registros cortesanos como devocionales: Daniel 6:12-14 la usa para su costumbre de orar tres veces al día. El raro Piel en Daniel 4:36 intensifica la búsqueda, sugiriendo la urgencia de los consejeros que ''buscaron'' al restaurado Nabucodonosor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1157', 'spa', 'En favor de; a través de; detrás de; alrededor de — preposición que expresa separación, paso o interposición', 'Preposición versátil construida sobre la idea de separación o interposición entre dos puntos. En su uso más frecuente significa ''en favor de'' o ''por causa de'', como cuando los sacerdotes hacen expiación por el pueblo. También indica movimiento físico a través de una abertura (Rajab descolgando a los espías por la ventana, Jos 2:15) y posición detrás de una barrera. Con menor frecuencia expresa protección envolvente, fundamento causal o un raro sentido temporal. El arco que va del espacial ''detrás'' al abstracto ''en favor de'' refleja un mismo hilo conceptual: algo que se interpone entre sujeto y objeto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1158', 'spa', 'Inquirir, buscar; hacer hervir, hinchar; (Nifal) ser escudrinado, abultarse.', 'Este raro verbo abarca un sorprendente rango semantico, desde la busqueda intelectual hasta la hinchazon fisica. En Isaias 21:12 aparece dos veces como invitacion a consultar al profeta sobre el destino de Edom. En Isaias 64:2 describe el fuego haciendo hervir el agua. Las formas Nifal aportan matices adicionales: en Abdias 1:6 los tesoros ocultos de Esau son ''escudrinados'', mientras que en Isaias 30:13 un muro agrietado se describe ''abultandose'' antes de desplomarse. El cognado arameo apoya el sentido de ''buscar/inquirir'', y el arabe anade la dimension de ''hinchar/supurar''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1160', 'spa', 'Beor — nombre propio: (1) padre de Bela, rey de Edom; (2) padre del profeta Balaam. Beor (בְּעוֹר) es un nombre personal que llevan dos figuras distin', 'Beor — nombre propio: (1) padre de Bela, rey de Edom; (2) padre del profeta Balaam. Beor (בְּעוֹר) es un nombre personal que llevan dos figuras distintas en la Biblia hebrea. El primero es el padre de Bela, un rey primitivo de Edom que reinó antes de cualquier rey israelita (Gn 36:32; 1 Cr 1:43). El segundo, mucho más prominente, es el padre de Balaam, el adivino mesopotámico convocado por Balac para maldecir a Israel (Nm 22:5; 24:3, 15; 31:8; Dt 23:5; Jos 13:22; 24:9; Mi 6:5). El patronímico «hijo de Beor» se convierte en un epíteto prácticamente fijo para Balaam. El nombre puede derivar de la raíz b-''-r, que significa «arder» o «consumir».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1162', 'spa', 'Boaz — pariente redentor de Rut en Belén; también el nombre del pilar izquierdo del templo de Salomón', 'Boaz — pariente redentor de Rut en Belén; también el nombre del pilar izquierdo del templo de Salomón');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1165', 'spa', 'Bestias, ganado — sustantivo colectivo para animales domésticos, especialmente bestias de carga', 'Sustantivo masculino colectivo (בְּעִיר) que designa animales domésticos o ganado en general, con cognados en diversas lenguas semíticas (arameo, siríaco, etiópico, árabe — donde se refiere específicamente al camello). En hebreo abarca bestias de carga como los asnos (Gn 45:17, en referencia a los asnos de los hermanos de José) y ganado en sentido amplio. Aparece en textos legales sobre daños causados por el ganado (Éx 22:4-5) y en la narrativa del desierto, donde Israel clama por agua para su ganado (Nm 20:4, 8, 11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1166', 'spa', 'Pocas raíces hebreas revelan supuestos culturales tan crudamente como בָּעַל. Su significado primario es ''casarse'' o ''ser esposo de'', pero simultáneam', 'Pocas raíces hebreas revelan supuestos culturales tan crudamente como בָּעַל. Su significado primario es ''casarse'' o ''ser esposo de'', pero simultáneamente conlleva ''ser dueño de, dominar'', porque en el mundo conceptual del antiguo Cercano Oriente, el esposo era el ''dueño'' (בַּעַל) del hogar. Isaías juega con ambos sentidos brillantemente: ''tu Hacedor es tu esposo'' (Is 54:5), donde Dios es simultáneamente cónyuge y soberano. El Dios de Jeremías dice: ''fui un esposo para ellos'' (Jer 31:32) — o quizás ''fui señor sobre ellos'' — y la ambigüedad es probablemente deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1167', 'spa', 'Dueño, amo, señor; esposo; señores/ciudadanos de una ciudad; poseedor de una cualidad (idiomático ''ba''al de X'').', 'Dueño, amo, señor; esposo; señores/ciudadanos de una ciudad; poseedor de una cualidad (idiomático ''ba''al de X'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1168a', 'spa', 'Baal — la deidad cananea de la tormenta; en plural Baalim, las diversas manifestaciones locales del culto a Baal.', 'Baal — la deidad cananea de la tormenta; en plural Baalim, las diversas manifestaciones locales del culto a Baal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1168b', 'spa', 'Baal (II); topónimo en Simeón y nombre propio de un rubenita y dos gabaonitas.', 'A diferencia del nombre de la deidad, este homógrafo funciona como topónimo y como nombre propio. Como lugar, designa una ciudad en el territorio tribal de Simeón (1 Cr 4:33), identificada con Baalat-Beer en otros pasajes. Como nombre propio, lo lleva un rubenita (1 Cr 5:5) y un antepasado gabaonita de Saúl registrado en 1 Crónicas 8:30 y 9:36. La asociación con la deidad cananea es incidental aquí: se trata simplemente de individuos y una ciudad que llevan un nombre semítico común que significa ''señor'' o ''amo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1169', 'spa', 'Señor, amo (arameo); título oficial que significa ''comandante'' o ''jefe administrativo'' en el Imperio persa', 'Palabra aramea que significa ''señor'' o ''amo'', cognada del hebreo בַּעַל. En Esdras aparece en el título ''beel teem'' (señor del decreto o comandante), designando a un funcionario persa encargado de la correspondencia y la administración, posiblemente un gobernador provincial. El título se usa tres veces en Esdras 4 (vv. 8, 9, 17) en cartas oficiales relativas a la reconstrucción de Jerusalén. Funciona como título burocrático dentro de la jerarquía imperial persa, no como nombre propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1171', 'spa', 'Baal-gad, localidad fronteriza septentrional que significa ''Baal de Gad/Fortuna''; al pie del monte Hermón', 'Topónimo que marca el límite territorial norte de Israel bajo Josué, con el significado de ''Baal de Gad'' (siendo Gad la divinidad de la fortuna). El sitio se hallaba ''en el valle del Líbano, al pie del monte Hermón'' (Josué 11:17; 13:5) y definía la extensión septentrional de las conquistas de Josué (Josué 12:7). El nombre indica un santuario cananeo donde se veneraba a Baal como Gad, dios de la fortuna. Entre las identificaciones propuestas figuran Banias (Cesarea de Filipo) y Hasbaya. La expresión ''desde Baal-gad'' funciona como referencia geográfica del alcance total de la conquista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1172', 'spa', 'Señora, dueña; mujer que posee o se caracteriza por algo: una casa, la hechicería o la nigromancia.', 'Forma femenina de בַּעַל (''señor, dueño''), usada para describir a una mujer definida por lo que posee o practica. En 1 Reyes 17:17, la ''señora de la casa'' (בַּעֲלַת הַבַּיִת) es la viuda de Sarepta que hospedó a Elías, un título digno de autoridad doméstica. En 1 Samuel 28:7, la misma construcción identifica a la célebre ''señora de un espíritu'' (בַּעֲלַת אוֹב), la médium de Endor a quien Saúl consultó. Nahúm 3:4 lo aplica a Nínive como ''señora de hechicerías'' (בַּעֲלַת כְשָׁפִים), personificando a la ciudad como una seductora encantadora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1173', 'spa', 'Baala: ciudad en Juda identificada con Quiriat-Jearim y Quiriat-Baal, antiguo centro de culto a Baal.', 'Baala es un toponimo en el territorio de Juda que significa ''senora'' o ''duena'', lo cual apunta a una asociacion anterior con el culto a Baal en un lugar alto local. Se identifica con Quiriat-Jearim (la ciudad de los bosques) y Quiriat-Baal (la ciudad de Baal), y aparece en las descripciones de los limites de Juda en Josue 15:9-11. Notablemente, 1 Cronicas 13:6 la menciona como el lugar desde el cual David traslado el arca. Una segunda Baala en Josue 15:29 corresponde a una poblacion en el distrito del Neguev.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1176', 'spa', 'Baal-zebub; deidad de Ecrón cuyo nombre significa ''señor de las moscas'', consultada por el rey Ocozías.', 'Nombre divino compuesto que significa ''señor de las moscas'', designando a la deidad filistea adorada en Ecrón. Las cuatro apariciones se encuentran en 2 Reyes 1:2-16, donde el rey Ocozías de Israel, tras caer por una celosía, envía mensajeros a consultar a Baal-zebub sobre si se recuperará. Elías los intercepta con una reprensión contundente: ''¿Acaso no hay Dios en Israel, que vais a consultar a Baal-zebub?'' El nombre puede ser una deformación hebrea deliberada de un original ''Baal-zebul'' (''señor de la morada exaltada''), convertido en ''señor de las moscas'' como insulto polémico contra el dios extranjero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1177', 'spa', 'Baal-Hanan: ''Baal es misericordioso''; nombre de un rey de Edom y de un supervisor gederatita bajo David.', 'Baal-Hanan es un nombre teoforico que significa ''Baal es misericordioso'', con paralelos en fenicio (Anibal invierte los mismos elementos) y asirio (Baalhanunu). Dos personajes llevan este nombre: un rey de Edom que sucedio a Saul (Gn 36:38-39; 1 Cr 1:49-50) y un gederatita designado sobre los olivares y sicomorales de David (1 Cr 27:28). La persistencia de ''Baal'' en un nombre administrativo israelita sugiere que, en esa epoca, ''baal'' aun funcionaba como titulo generico (''senor'') y no se referia exclusivamente a la deidad cananea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1181', 'spa', 'Baal, dueño, señor, amo; dios cananeo de la tormenta cuyo título se convirtió en nombre propio', 'Este sustantivo común que significa «dueño» o «señor» se aplicaba a posesiones, tierras o relaciones (especialmente el matrimonio), pero se hizo tristemente célebre como el título convertido en nombre de la deidad principal de Canaán. Baal controlaba las tormentas, la lluvia y la fertilidad, compitiendo directamente con el papel de Yahvé. La tentación de Israel de adorar a Baal alcanzó su punto crítico durante el reinado de Acab, culminando en el desafío de Elías en el Carmelo. Los profetas condenaron el culto a Baal como adulterio contra el pacto. Los escritores bíblicos a veces deformaban deliberadamente los nombres compuestos con Baal, sustituyendo ese elemento por «bóshet» (vergüenza). Sin embargo, «baal» conservó su sentido ordinario de dueño o esposo en contextos seculares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1186', 'spa', 'Baal-meón, ciudad moabita que significa ''Baal de la morada''; reconstruida por Rubén y luego reclamada por Moab', 'Ciudad de Transjordania, al este del mar Muerto, cuyo nombre significa ''Baal de la morada''. Fue reconstruida por los rubenitas tras la conquista israelita del territorio de Sijón (Números 32:38) y habitada por los descendientes de Rubén (1 Crónicas 5:8). Para la época de Ezequiel, había vuelto a control moabita (Ezequiel 25:9). La ciudad también aparece como ''Bet-baal-meón'' y como ''Beón'' (Números 32:3). La Estela de Mesa confirma su importancia en la historia moabita. El nombre señala un santuario de Baal, reflejo del sincretismo religioso de la región.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1187', 'spa', 'Baal Peor — la deidad moabita Baal venerada en Peor y el sitio de la apostasía de Israel', 'Baal Peor se refiere a la deidad local Baal adorada en el monte o santuario llamado Peor en Moab. El nombre es inseparable de la célebre apostasía en Sitim (Num 25:1-9), donde los israelitas participaron en el culto licencioso moabita y provocaron una plaga devastadora. Moisés cita el episodio como advertencia (Deut 4:3), el salmista lo relata como paradigma de infidelidad (Sal 106:28) y Oseas recurre al mismo evento para diagnosticar la idolatría persistente de Israel (Os 9:10). Las seis ocurrencias giran en torno a este único referente histórico-teológico. Las traducciones en todas las lenguas preservan uniformemente el nombre compuesto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1188', 'spa', 'Baal-perazim, topónimo que significa ''señor de las brechas'', sitio de la victoria de David sobre los filisteos.', 'Topónimo que combina ''baal'' (señor, dueño) y ''perazim'' (brechas, rupturas), conmemorando la victoria decisiva de David sobre los filisteos. En aquel lugar David declaró: ''El SEÑOR ha irrumpido contra mis enemigos delante de mí, como brecha de aguas'' (2 Sam 5:20). El nombre encierra así un juego de palabras teológico: Dios mismo fue el verdadero ''señor de las brechas''. La ubicación exacta se desconoce, aunque se hallaba cerca del valle de Refaím, a las afueras de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1189', 'spa', 'Baal-zefón, topónimo egipcio que significa ''Baal del norte''; cerca del lugar donde Israel cruzó el mar Rojo', 'Nombre de una localidad egipcia que significa ''Baal del norte'' (Zefón era un título divino), donde los israelitas acamparon antes de cruzar el mar Rojo. Israel acampó ''frente a Baal-zefón'' junto al mar (Éxodo 14:2, 9; Números 33:7), en un sitio del noreste de Egipto. El nombre indica la presencia de un santuario dedicado a Baal-Zefón, deidad cananea de la tormenta venerada en Egipto. Identificaciones propuestas incluyen el monte Ataka o un lugar cerca de los Lagos Amargos. El campamento junto a este santuario pagano prepara el escenario para el triunfo de Yahvé sobre Faraón y, simbólicamente, sobre los dioses de Egipto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1191', 'spa', 'Baalat, ciudad en Dan y en los proyectos de construcción de Salomón; nombre que significa ''señora'' o lugar de culto a Baal', 'Nombre de una ciudad que aparece en la heredad de la tribu de Dan (Josué 19:44) y entre las ciudades fortificadas por Salomón (1 Reyes 9:18; 2 Crónicas 8:6). El nombre significa ''señora'' o ''dama'', lo cual sugiere que el lugar estaba asociado con el culto a Baal o a una divinidad femenina. La actividad constructora de Salomón allí indica importancia estratégica, posiblemente defensiva o administrativa. Su ubicación exacta es incierta; se ha propuesto el sitio de Bala''in en la Sefelá. La presencia de esta ciudad tanto en las listas territoriales como en los proyectos reales muestra su relevancia continuada desde el período del asentamiento hasta la monarquía unida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1195', 'spa', 'Baana, nombre propio que posiblemente significa ''hijo de aflicción''; gobernador de Salomón y líder postexílico', 'Nombre propio de varios individuos, que posiblemente significa ''hijo de aflicción'' o ''hijo de angustia''. Dos de los doce gobernadores de distrito de Salomón se llamaban Baana: uno administraba Taanac y Meguido (1 Reyes 4:12) y el otro gobernaba Aser y Alot (1 Reyes 4:16). También aparece un Baana como antepasado de un constructor postexílico que reparó la muralla de Jerusalén (Nehemías 3:4). La recurrencia del nombre en distintas épocas sugiere que era frecuente en la onomástica israelita. El papel de los gobernadores indica competencia administrativa y confianza real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1196', 'spa', 'Baaná, nombre propio de varios hombres, incluido un capitán que asesinó a Isboset y un líder postexílico.', 'Nombre propio masculino que aparece en diversos períodos de la historia de Israel. El Baaná más destacado es el capitán benjaminita que, junto con su hermano Recab, asesinó al hijo de Saúl, Isboset, acto por el cual David los mandó ejecutar (2 Sam 4:2-9). Otro Baaná fue padre de Heleb, uno de los valientes de David (2 Sam 23:29). El nombre reaparece en contextos postexílicos entre los líderes que regresaron de Babilonia (Esd 2:2; Neh 7:7) y entre quienes sellaron el pacto (Neh 10:28). En español se observa variación interesante entre «Baana» y «Baaná».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1197a', 'spa', 'Arder, estar en llamas (Qal); encender, prender fuego (Piel/Hifil); purgar o eliminar el mal de la comunidad.', 'Arder, estar en llamas (Qal); encender, prender fuego (Piel/Hifil); purgar o eliminar el mal de la comunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1197b', 'spa', 'Ser embrutecido o necio como un animal; también: apacentar, dejar que el ganado paste en un campo.', 'Verbo denominativo de be''ir («bestia, ganado»), con dos perfiles semánticos bastante distintos. En su uso profético principal significa «ser embrutecido, necio, torpe de corazón», comportándose con la naturaleza irracional de un animal en vez de como un ser humano capaz de razonar. Isaías califica de «embrutecidos» a los consejeros de Egipto (Is 19:11), el salmista reprende a los insensatos del pueblo (Sal 94:8) y Jeremías condena repetidamente a quienes son «demasiado necios para conocer a Dios» (Jer 10:8, 14, 21). El segundo sentido, atestiguado en el Código de la Alianza (Éx 22:5), es agrícola: apacentar o dejar que el ganado propio paste en campo ajeno, un uso concreto y legal que conserva la conexión etimológica con el ganado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1198', 'spa', 'Brutalidad, estupidez; usado sustantivamente para designar al bruto o insensato que carece de comprension moral y espiritual.', 'Este sustantivo poetico denota una estupidez cruda, casi animal: la incapacidad de percibir las obras de Dios o las realidades morales. El salmista empareja al bruto con el necio (כְּסִיל) en los Salmos 49:10 y 92:6, mientras que en el Salmo 73:22 el hablante confiesa haber sido ''bruto'' ante Dios al envidiar a los malvados. Proverbios 12:1 declara que quien aborrece la correccion es bruto, y la humildad de Agur en Proverbios 30:2 lo emplea como autodesprecio. El espectro va desde la torpeza obstinada hasta la confesion de limitacion humana ante lo divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1201', 'spa', 'Baasa — rey de Israel (ca. 909-886 a.C.) que derrocó la dinastía de Jeroboam y guerreó contra Judá', 'Baasa — rey de Israel (ca. 909-886 a.C.) que derrocó la dinastía de Jeroboam y guerreó contra Judá');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1204', 'spa', 'Una palabra que resuena con pavor a lo largo de los libros poéticos, בָּעַת capta el terror repentino y abrumador — el tipo que cae sobre una persona ', 'Una palabra que resuena con pavor a lo largo de los libros poéticos, בָּעַת capta el terror repentino y abrumador — el tipo que cae sobre una persona sin aviso. Job la usa más que cualquier otro autor bíblico, clamando: ''Me espantas con sueños y me aterras con visiones'' (Job 7:14), y después: ''terrores se vuelven contra él'' (Job 18:11). El cognado árabe بَغَتَ (''llegar de repente'') ilumina el núcleo de la raíz: no es ansiedad gradual sino terror que golpea. El Nifal pasivo aparece en momentos dramáticos — Ester 7:6, donde Amán ''fue aterrorizado'' ante el rey y la reina, y Daniel 8:17, donde el profeta cae postrado en terror ante la visión angélica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1207', 'spa', 'Pantano, ciénaga, terreno anegado donde crecen juncos y papiros.', 'Se refiere a un terreno pantanoso y anegado donde prosperan el papiro y los juncos. En Job 8:11 aparece en una pregunta retórica sobre si los juncos pueden crecer sin ciénaga, ilustrando la dependencia de la vida respecto a su entorno adecuado. Job 40:21 emplea la palabra para describir el hábitat de Behemot. Ezequiel 47:11 contrasta el río vivificante de la visión del templo con los pantanos estancados que permanecen salados y sin sanidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1209', 'spa', 'Bezai, nombre de familia; clan postexílico que regresó de Babilonia y selló el pacto de Nehemías', 'Nombre de familia que aparece en las listas de retorno del exilio y en el pacto de renovación. Los ''hijos de Bezai'' sumaban 323 (Esdras 2:17) o 324 (Nehemías 7:23) entre quienes regresaron con Zorobabel. Un líder llamado Bezai selló el pacto de Nehemías (Nehemías 10:18). El nombre podría significar ''conquistador'' o derivar de una raíz que significa ''botín''. La leve discrepancia numérica (323 frente a 324) es típica de listas paralelas de retorno, posiblemente debida a la transmisión textual o al método de recuento. Bezai representa a una familia laica que sobrevivió al exilio y participó en la renovación del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1210', 'spa', 'Vendimia, cosecha de uvas — la recolección estacional de uvas del viñedo', 'Sustantivo masculino (בָּצִיר) derivado del verbo בָּצַר (''cortar, vendimiar''), que designa la vendimia o cosecha de uvas. Marca un momento clave en el calendario agrícola del antiguo Israel: la temporada de recolección de la uva, que seguía a las cosechas de trigo y cebada. En Levítico 26:5, una vendimia abundante se promete como bendición del pacto: «vuestra trilla alcanzará a la vendimia». También funciona como metáfora de juicio y desolación, como cuando Miqueas lamenta ser como los rebuscos después de la vendimia (Mi 7:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1212', 'spa', 'Betsalel, ''a la sombra de Dios,'' maestro artesano del Tabernáculo; también un israelita postexílico.', 'Nombre teofórico que significa ''a la sombra (protección) de Dios,'' portado principalmente por el artesano principal del Tabernáculo, designado por Dios mismo. Dios llenó a Betsalel hijo de Uri con su Espíritu, otorgándole habilidad extraordinaria en el trabajo de metales, talla de piedras y madera para construir los utensilios sagrados (Éx 31:2; 35:30; 36:1-2). Se le atribuye la construcción del Arca misma (Éx 37:1) y la supervisión de toda la obra del Tabernáculo (Éx 38:22). Un segundo Betsalel aparece entre quienes habían tomado mujeres extranjeras durante la reforma de Esdras (Esd 10:30).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1214', 'spa', 'El verbo hebreo batsa'' lleva la vívida imagen física de cortar o cercenar, que luego se extiende en dos direcciones distintas. Por un lado desarrolla ', 'El verbo hebreo batsa'' lleva la vívida imagen física de cortar o cercenar, que luego se extiende en dos direcciones distintas. Por un lado desarrolla el sentido moral de ''cortar'' ganancia para uno mismo — codiciar ganancia injusta, como Jeremías denuncia repetidamente (Jer 6:13; 8:10). Por el otro se mueve hacia la idea de ''abrirse paso'' hasta la conclusión, como cuando Zacarías declara que las manos de Zorobabel terminarán el Templo (Zac 4:9). La imagen del tejedor en Isaías 38:12, donde Dios corta a Ezequías del telar de la vida, conecta bellamente lo literal con lo figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1215', 'spa', 'Ganancia injusta, codicia; provecho o ventaja; botín o despojos de guerra', 'Ganancia injusta, codicia; provecho o ventaja; botín o despojos de guerra');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1217', 'spa', 'Masa, especialmente masa sin fermentar o sin levadura en proceso de ser amasada o preparada para hornear.', 'Este sustantivo designa la masa en cualquier fase previa al horneado, aunque sus apariciones más memorables destacan el estado sin fermentar. En el relato del Éxodo (12:34, 39), los israelitas cargan su masa antes de que haya leudado, envuelta en sus ropas mientras huyen de Egipto. En otros contextos no lleva tal restricción: Tamar amasa para Amnón (2 Sam 13:8), mujeres en Jerusalén amasan tortas para la Reina del Cielo (Jer 7:18), y Oseas la emplea en una metáfora de panadería (Os 7:4). El español ''masa'' capta directamente el sentido culinario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1219', 'spa', 'Cortar o hacer inaccesible mediante fortificación; también recoger uvas, vendimiar una viña', 'Cortar o hacer inaccesible mediante fortificación; también recoger uvas, vendimiar una viña');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1221', 'spa', 'Beser: (1) ciudad levítica de refugio en el territorio de Rubén; (2) descendiente de Aser. Significa ''fortaleza''.', 'Beser funciona como topónimo y como nombre personal, enraizado en la idea de ''fortaleza'' o ''recinto fortificado''. Como ciudad, fue designada una de las tres ciudades de refugio al este del Jordán, asignada a la tribu de Rubén (Dt 4:43; Jos 20:8; 21:36) y entregada posteriormente a los levitas meraritas (1 Cr 6:78). La Estela de Moab (Inscripción de Mesa) también menciona un lugar llamado Beser, confirmando su realidad histórica y geográfica. Como nombre personal, Beser aparece como descendiente de Aser en 1 Crónicas 7:37. En español se alterna entre ''Beser'' y ''Betser'', reflejando la dificultad de transliterar la tsade hebrea en las lenguas romances.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1224', 'spa', 'Bosra — ciudad fortificada de Edom (y posiblemente de Moab), símbolo del juicio divino en la literatura profética.', 'Topónimo que significa ''fortaleza'' (de בָּצַר, ''fortificar''), que identifica la ciudad principal de Edom, la actual Buseirah en el sur de Jordania. En Génesis 36:33 es la patria del rey edomita Jobab, y en los profetas se convierte en un poderoso símbolo del juicio de Dios contra Edom (Is 34:6; 63:1; Jer 49:13, 22; Am 1:12). Jeremías 48:24 aplica el nombre a una ciudad moabita, posiblemente la misma que Beser. Las variantes en español Bosra y Botsra conservan las consonantes semíticas originales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1228', 'spa', 'Frasco, vasija (por el sonido de gorgoteo al vaciarse); recipiente de barro, especialmente para aceite', 'Frasco o vasija cuyo nombre proviene del sonido de gorgoteo que produce al vaciarse. El término aparece en relatos que involucran actos simbólicos o regalos. La esposa de Jeroboam lleva ''un frasco de miel'' junto con otros presentes al profeta Ahías (1 Reyes 14:3). Jeremías recibe la orden de comprar un frasco de barro y quebrarlo públicamente como señal de la destrucción venidera de Jerusalén (Jeremías 19:1, 10). El nombre onomatopéyico (בַּקְבֻּק, que imita el sonido del líquido) subraya la función del recipiente. La rotura del frasco se convierte en una poderosa profecía actuada de juicio irreversible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1229', 'spa', 'Bacbuquías — un levita portero en la Jerusalén postexílica', 'Bacbuquías aparece únicamente en las listas de Nehemías entre los levitas que regresaron del exilio y sirvieron en el templo reconstruido. Se le menciona entre los porteros y los que ofrecían acciones de gracias (Neh 11:17; 12:9, 25). Su nombre podría derivar de una raíz que significa ''vaciar'' (como una botella), aunque esto es incierto. Representa a uno de los muchos fieles servidores del templo cuyos nombres quedaron preservados en la memoria genealógica de las Escrituras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1231', 'spa', 'Buqui: nombre propio de un jefe danita y de un descendiente de Aarón en la línea sacerdotal.', 'Buqui es un nombre personal que aparece en dos contextos genealógicos distintos. Primero, se trata de un jefe de la tribu de Dan comisionado para ayudar a repartir la tierra de Canaán entre las tribus (Nm 34:22). Segundo, un Buqui diferente figura en el linaje sacerdotal que desciende de Aarón a través de Eleazar y Finees (1 Cr 6:5, 51; Esd 7:4), formando un eslabón en la cadena de sucesión sumo-sacerdotal. La etimología del nombre es debatida, pero podría relacionarse con una forma teofórica abreviada. Las traducciones principales conservan el nombre con variación mínima: en español ''Buqui'', en francés y alemán ''Bukki''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1234', 'spa', 'Hender, partir, abrir brecha; del agua: brotar; de muros: romper; de huevos: empollar.', 'Hender, partir, abrir brecha; del agua: brotar; de muros: romper; de huevos: empollar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1237', 'spa', 'Un valle amplio o llanura abierta entre montañas; una tierra baja extensa y nivelada. Derivado de la raíz בקע (''hendir, partir''), este sustantivo evoc', 'Un valle amplio o llanura abierta entre montañas; una tierra baja extensa y nivelada. Derivado de la raíz בקע (''hendir, partir''), este sustantivo evoca un amplio valle de grieta o llanura abierta — terreno que ha sido ''hendido'' entre cadenas montañosas. Describe la llanura de Sinar donde la humanidad se reunió para construir Babel (Gn 11:2), el valle-llanura donde Ezequiel contempló la gloria del Señor (Ez 3:22–23) y el valle de los huesos secos (Ez 37:1–2), así como regiones geográficas específicas como el valle de Jericó (Dt 34:3) y el valle del Líbano (Jos 11:17). La palabra aparece frecuentemente en estado constructo con nombres de lugares, sirviendo como descriptor geográfico para tierras bajas amplias y fértiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1238b', 'spa', 'Vaciar, devastar, asolar; en pasivo, ser vaciado o quedar desolado. Se usa para el juicio divino sobre tierras y pueblos.', 'Verbo de destrucción y desolación que describe cómo la vida y la sustancia se drenan de una tierra o un pueblo. En sus formas activas (Qal, Poel), describe a Dios vaciando la tierra (Is 24:1), a guerreros devastando a Judá (Nah 2:2) y al consejo divino anulando los planes (Jer 19:7). Las formas pasivas del Nifal retratan el estado resultante de desolación: ''la tierra será enteramente vaciada'' (Is 24:3). El probable cognado árabe baqqa, que describe el sonido del agua al verterse, evoca la vívida imagen auditiva detrás de esta palabra: una tierra drenada como un recipiente volcado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1239', 'spa', 'Inquirir, escudriñar, examinar o reflexionar; Piel intensivo de investigación cuidadosa, inspección o contemplación', 'Verbo usado exclusivamente en la conjugación Piel, que transmite una búsqueda o investigación deliberada y enfocada. Cuando Dios promete «buscar» a sus ovejas dispersas (Ez 34:11-12), la palabra lleva el peso de la búsqueda decidida de un pastor. En contextos sacerdotales denota un examen formal, como cuando el sacerdote inspecciona la piel en busca de enfermedad (Lv 13:36). En su sentido más reflexivo, el término se desplaza hacia la contemplación interior: el salmista anhela «inquirir» en el templo de Dios (Sal 27:4), y el sabio advierte contra los votos precipitados instando a «considerar» después (Pr 20:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1240', 'spa', 'Buscar, indagar, investigar; verbo arameo usado exclusivamente en Esdras para pesquisas archivísticas oficiales.', 'Verbo arameo que aparece únicamente en Esdras, empleado para el acto de realizar una búsqueda o indagación oficial, particularmente en archivos reales. Cada aparición involucra una investigación gubernamental, ya sea escudriñando registros para verificar alegatos sobre la historia rebelde de Jerusalén (Esd 4:15, 19) o localizando el decreto original de Ciro (Esd 6:1). Las traducciones españolas ''investigar'' y ''sea buscado'' captan bien ambas dimensiones, activa y pasiva: uno puede buscar deliberadamente o una búsqueda puede ser ordenada de forma impersonal. El término subraya cómo el procedimiento burocrático determinó el destino de los exiliados que retornaban.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1241', 'spa', 'Ganado vacuno, manada — sustantivo colectivo para el ganado bovino, ya sea como grupo o como bueyes y vacas individuales', 'El hebreo בָּקָר designa al ganado bovino como colectivo, abarcando manadas de bueyes y vacas ya sea pastando, en sacrificio o arando. La raíz del vocablo se vincula con la labranza, reflejo del papel económico primordial del animal en el antiguo Oriente Próximo. Aparece junto a צֹאן (rebaño) en el emparejamiento clásico de ganado (Gn 12:16; 1 S 11:7). Las traducciones en diversas lenguas lo vierten de manera uniforme con términos de animales de manada: español ganado vacuno, francés bétail, alemán Rind/Herde, apuntando todas a un núcleo semántico estable de bovinos domesticados como unidad de riqueza pastoril.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1242', 'spa', 'Mañana — la parte temprana del día, desde el alba hasta el mediodía; usado del tiempo, el sacrificio y la fidelidad divina', 'בֹּקֶר designa la mañana, el momento en que la oscuridad cede ante la luz. Derivado de una raíz que significa ''hendir o penetrar'', evoca el alba abriéndose paso a través de la noche. Aparece en contextos rituales (el sacrificio matutino, Ex 29:39), en la narrativa (Abraham levantándose de madrugada, Gn 22:3) y en declaraciones poéticas sobre la fidelidad divina que se renueva cada mañana (Lm 3:23). La expresión ''desde la tarde hasta la mañana'' marca el ciclo diario en el cómputo sacerdotal. El español mañana, el francés matin y el alemán Morgen lo traducen de manera constante, capturando tanto la referencia temporal como las connotaciones esperanzadoras de un nuevo día.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1245', 'spa', 'Buscar, requerir, suplicar; el Piel intensivo de búsqueda activa de personas, cosas, justicia o favor divino', 'Uno de los verbos más frecuentes de la Biblia hebrea, בִּקֵּשׁ en Piel transmite una búsqueda intensiva y deliberada. Abarca desde el acto concreto de buscar asnas perdidas (1 S 9:3) hasta la grave demanda de Dios requiriendo la sangre de manos de alguien (Gn 9:5). Los cognados árabes طَلَبَ y بَحَثَ captan este mismo espectro, de la indagación casual a la exigencia urgente. En su sentido peticionario, el vocablo colorea algunas de las oraciones más conmovedoras de la Escritura, como cuando la comitiva de Esdras buscó a Dios mediante el ayuno (Esd 8:21). El Pual pasivo completa el cuadro, describiendo lo que ocurre cuando lo buscado es investigado o escudriñado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1246', 'spa', 'Solicitud, petición, súplica — ruego formal dirigido especialmente ante la realeza.', 'Sustantivo femenino que designa una solicitud o petición formal, usado casi exclusivamente en los diálogos cortesanos de Ester y una vez en Esdras. El empleo reiterado de esta palabra por la reina Ester ante el rey Asuero (Est 5:3, 6-8; 7:2-3; 9:12) la convierte en el término por excelencia para la súplica real en el hebreo bíblico tardío. Los vocablos españoles solicitud y súplica captan tanto el registro formal como el emocional. En Esdras 7:6, el rey concede la בַּקָּשָׁה de Esdras, su petición formal para el retorno a Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1247', 'spa', 'Hijo (arameo) — usado en patronímicos, expresiones colectivas y la frase mesiánica ''hijo de hombre.''', 'Palabra aramea para ''hijo,'' cognada del hebreo בֵּן, que aparece en las porciones arameas de Esdras y Daniel. Funciona en cadenas patronímicas (''hijo de X''), en expresiones colectivas como ''hijos de Israel'' (Esd 6:16) e ''hijos del cautiverio'' (Dn 2:25; 5:13; 6:14), y de manera memorable en la expresión visionaria בַּר אֱנָשׁ, ''hijo de hombre'' (Dn 7:13). Esta última frase adquirió enorme relevancia teológica en la tradición posterior. El término es el equivalente arameo del hebreo בֵּן, con la terminación en nun típica de las lenguas arameas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1248', 'spa', 'Hijo (préstamo arameo usado en poesía hebrea tardía, especialmente en Sal 2:12 y Prov 31:2).', 'Palabra de origen arameo que significa ''hijo'', presente en solo dos contextos bíblicos. En Proverbios 31:2 la madre del rey Lemuel se dirige a él tiernamente tres veces como ''hijo mío'', usando la forma aramea en lugar del hebreo estándar בֵּן. En el Salmo 2:12, la célebre exhortación ''besad al Hijo'' ha generado siglos de debate interpretativo: la Septuaginta traduce ''aferraos a la instrucción'', mientras que la Peshitta y muchas versiones modernas leen ''besad al Hijo'' como un imperativo mesiánico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1249', 'spa', 'Puro, limpio, sincero — describe claridad moral del corazón, limpieza ritual o vacuidad física', 'Adjetivo (בַּר) que significa ''puro'' o ''limpio'', empleado en contextos éticos, litúrgicos e incluso cotidianos. En los Salmos describe la pureza moral necesaria para presentarse ante Dios: «manos limpias y corazón puro» (Sal 24:4) y aquellos de «corazón puro» hacia quienes Dios es bueno (Sal 73:1). Los mandamientos del Señor se llaman בָּרָה, ''puros'' (Sal 19:9). En Proverbios 14:4, describe un pesebre vacío y limpio: sin bueyes el pesebre está limpio, pero tampoco hay cosecha. Esta amplitud semántica, desde la pureza moral interior hasta la vacuidad física, otorga a esta palabra un alcance distintivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1250a', 'spa', 'Grano, cereal; trigo — grano trillado, especialmente almacenado o comercializado', 'El sustantivo בַּר designa grano trillado — cereal limpio y aventado, listo para almacenamiento, venta o transporte. Aparece de forma prominente en la narrativa de José, donde el faraón ordena reunir grano durante los siete años de abundancia (Gn 41:35, 49) y Jacob envía a sus hijos a Egipto a comprar grano (Gn 42:3, 25). En la literatura profética, Amós condena a quienes manipulan el comercio del grano (Am 5:11; 8:5–6), y Jeremías contrasta grano y paja como metáforas de la profecía verdadera y la falsa (Jer 23:28). El cognado árabe burr (trigo) y las traducciones multilingües coincidentes — ''grano'' (español), ''blé/grain'' (francés), ''Getreide/Korn'' (alemán) — señalan el grano de cereal como referente central.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1251', 'spa', 'Campo abierto, tierra silvestre (arameo) — la tierra no cultivada donde habitan los animales salvajes.', 'Sustantivo arameo que designa el campo abierto o la tierra silvestre, equivalente al hebreo sadeh. Aparece exclusivamente en los capítulos arameos de Daniel, casi siempre en la frase khevat bar (''bestias del campo''), describiendo a los animales salvajes que habitan terrenos no cultivados. En la visión del árbol de Nabucodonosor (Dan 4), es el campo abierto donde el propio rey morará entre las bestias como juicio divino. Las traducciones en español ''campo'', en francés champ y en alemán Feld convergen uniformemente en el sentido de terreno exterior no cultivado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1252', 'spa', 'Limpieza, pureza, inocencia — pureza moral de las manos o la conducta, en declaraciones de integridad ante Dios.', 'Sustantivo masculino que denota limpieza o pureza, usado exclusivamente en declaraciones poéticas de inocencia ante Dios. David lo emplea en su salmo de victoria para afirmar que Dios le retribuyó ''conforme a la limpieza de mis manos'' (2 Sam 22:21, paralelo en Sal 18:20, 24), mientras que Job 22:30 aplica la imagen de ''la pureza de las palmas'' a la persona inocente a quien Dios libra. El español ''limpieza'' y ''pureza'' captan conjuntamente el doble matiz: tanto la limpieza física como la pureza moral están en juego, pues la mano exterior simboliza la integridad interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1254a', 'spa', 'Crear (Qal), ser creado (Nifal), o talar/desmontar (Piel); en Qal se usa exclusivamente para la creación divina, con un sentido de Piel completamente ', 'Crear (Qal), ser creado (Nifal), o talar/desmontar (Piel); en Qal se usa exclusivamente para la creación divina, con un sentido de Piel completamente distinto: cortar árboles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1259', 'spa', 'Granizo, piedras de granizo — fenómeno meteorológico destructivo empleado como juicio divino', 'Granizo, piedras de granizo — fenómeno meteorológico destructivo empleado como juicio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1261', 'spa', 'Manchado, moteado; que presenta parches irregulares de color contrastante (dicho de ganado y caballos)', 'Adjetivo que describe animales cuyo pelaje exhibe manchas o parches irregulares de color contrastante. Aparece en Génesis junto a otros dos adjetivos — ''listado'' y ''salpicado'' — en las negociaciones de Jacob con Labán sobre los rebaños (Gn 31:10, 12). En Zacarías 6:3, 6 describe uno de los equipos de caballos entre los cuatro carros que salen de entre dos montañas de bronce. La raíz podría vincularse con ''granizo'' (בָּרָד), sugiriendo un pelaje ''salpicado'' de marcas como si hubiera sido golpeado por piedras de granizo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1262', 'spa', 'Comer, tomar alimento; también elegir o seleccionar — verbo hebreo poco frecuente para comer, con un caso que significa ''elegir''', 'בָּרָה es un verbo relativamente poco frecuente cuyo sentido principal es ''comer'' o ''tomar alimento'', y aparece casi exclusivamente en las narrativas de David en 2 Samuel. Funciona en varias conjugaciones: Qal ''comer'' (2 S 12:17; 13:6, 10), Hifil ''hacer comer, alimentar'' (2 S 3:35; 13:5) y Piel ''devorar'' (Lm 4:10). Una única aparición en 1 Samuel 17:8 lleva el significado completamente distinto de ''elegir'': el desafío de Goliat «elegid para vosotros un hombre», que algunos eruditos atribuyen a una raíz distinta o a una variante escribal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1263', 'spa', 'Baruc — ''bendito''; nombre del escriba de Jeremías y de varias figuras postexílicas', 'Baruc — ''bendito''; nombre del escriba de Jeremías y de varias figuras postexílicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1265', 'spa', 'Ciprés — una conífera alta apreciada por su madera en la construcción del templo y la fabricación de barcos. Se refiere al ciprés (o posiblemente abet', 'Ciprés — una conífera alta apreciada por su madera en la construcción del templo y la fabricación de barcos. Se refiere al ciprés (o posiblemente abeto o enebro), una conífera majestuosa que crecía en las montañas del Líbano y era muy valorada por su madera fina y duradera. Salomón importó madera de ciprés junto con cedro para la construcción del templo (1 R 5:8, 10; 6:15, 34), y se usaba para instrumentos musicales en las celebraciones (2 S 6:5). La identificación botánica exacta ha sido debatida desde la antigüedad — la Septuaginta y la Peshitta favorecen el ciprés, mientras que la Vulgata de Jerónimo se inclina hacia el abeto o pino — pero la Biblia hebrea lo trata consistentemente como una madera de construcción de primera calidad, solo superada por el cedro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1270', 'spa', 'Hierro — el metal en forma bruta, trabajada o figurada, que simboliza fuerza, dureza y severidad inflexible.', 'Hierro — el metal en forma bruta, trabajada o figurada, que simboliza fuerza, dureza y severidad inflexible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1271', 'spa', 'Barzilai — nombre propio, principalmente el acaudalado galaadita que sostuvo a David durante la revuelta de Absalón. Barzilai (barzillay, «hombre de h', 'Barzilai — nombre propio, principalmente el acaudalado galaadita que sostuvo a David durante la revuelta de Absalón. Barzilai (barzillay, «hombre de hierro», de barzel, «hierro») es un nombre propio que designa principalmente a Barzilai el galaadita, un anciano y rico varón de Roguelim que proveyó víveres a David y su séquito durante su huida de Absalón al otro lado del Jordán (2 S 17:27-29). Cuando David regresó triunfante, Barzilai, de ochenta años, le salió al encuentro en el Jordán, pero declinó la invitación del rey de ir a Jerusalén, alegando su avanzada edad y la mengua de sus sentidos (2 S 19:31-39). David encargó a Salomón que mostrara lealtad a los hijos de Barzilai (1 R 2:7). Una familia sacerdotal también llevó este nombre, al haberse emparentado con los descendientes de Barzilai (Esd 2:61; Neh 7:63).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1272', 'spa', 'Huir o escapar; en Hifil, ahuyentar o poner en fuga; también de una barra que atraviesa o pasa de un lado a otro.', 'Huir o escapar; en Hifil, ahuyentar o poner en fuga; también de una barra que atraviesa o pasa de un lado a otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1277', 'spa', 'Gordo, rollizo, bien alimentado; que describe ganado o personas saludables y bien nutridas', 'Adjetivo que significa gordo, rollizo o bien alimentado. Aparece de manera destacada en el sueño del faraón, donde siete vacas gordas salen del Nilo antes de ser devoradas por siete flacas (Gn 41:2, 4, 5, 7, 18, 20). El término se extiende al ganado cebado en contextos de templo y corte (1 R 5:3; Ez 34:3, 20; Zac 11:16) e incluso a la apariencia saludable de Daniel y sus compañeros tras su dieta de legumbres (Dn 1:15). En el Salmo 73:4 describe a los impíos prósperos, cuyos cuerpos están ''gordos''. Las traducciones al español (''gordas'') y al alemán (''die fetten'') confirman el sentido físico directo de gordura y prosperidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1279', 'spa', 'El alimento, sustento especialmente preparado — usado de la comida de Amnón durante su fingida enfermedad', 'Este sustantivo poco frecuente aparece únicamente en la trágica narración de Amnón y Tamar (2 Sam 13:5-10). Se refiere a un alimento preparado con esmero para alguien enfermo o que finge estarlo, con un sentido de ''sustento restaurador'' o ''manjar reconfortante''. Amnón pide que Tamar le prepare esta comida con sus propias manos, convirtiendo lo que debía ser un acto de cuidado en ocasión para la violencia. La rareza de la palabra refleja su significado especializado: no cualquier alimento, sino nutrición preparada con particular dedicación para el convaleciente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1280', 'spa', 'Barra, cerrojo, travesaño para puertas o armazón estructural; también (como homógrafo) un fugitivo, uno que huye', 'Barra, cerrojo, travesaño para puertas o armazón estructural; también (como homógrafo) un fugitivo, uno que huye');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1281', 'spa', 'Huidizo, fugitivo — usado de serpientes cósmicas y de refugiados humanos', 'Este adjetivo describe un movimiento de huida rápido y sinuoso. Aparece en dos imágenes mitológicas impactantes: la ''serpiente huidiza'' de Job 26:13 (posiblemente un dragón de eclipse) y el Leviatán, ''serpiente veloz'' de Isaías 27:1 (probablemente figurativo para Asiria). En Isaías 43:14 el sentido cambia a fugitivos humanos que huyen de Babilonia. La palabra capta tanto el movimiento ondulante de una serpiente como la desesperada premura de los refugiados. BDB señala que equivale a la forma más común בָּרִיחַ, lo que sugiere grafías intercambiables para este vívido término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1283', 'spa', 'Bería — nombre personal que llevan varios israelitas, sobre todo un hijo de Aser y un hijo de Efraín nombrado en aflicción. Bería (בְּרִיעָה) es un no', 'Bería — nombre personal que llevan varios israelitas, sobre todo un hijo de Aser y un hijo de Efraín nombrado en aflicción. Bería (בְּרִיעָה) es un nombre personal que llevan al menos cuatro individuos en el Antiguo Testamento, con una etimología popular que lo vincula a רָעָה («mal, desgracia»). El portador más conmovedor es un hijo de Efraín, llamado Bería «porque la desgracia había caído sobre su casa», tras la muerte de sus hermanos a manos de los hombres de Gat en una incursión ganadera (1 Cr 7:23). El Bería más antiguo y genealógicamente prominente es un hijo de Aser (Gn 46:17; Nm 26:44-45), ancestro del clan de los beriaítas. Un tercer Bería aparece entre los benjaminitas de Ajalón que expulsaron a los habitantes de Gat (1 Cr 8:13, 16). Un cuarto es un levita, hijo de Simei en la línea gersonita (1 Cr 23:10-11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1285', 'spa', 'Pacto, alianza, tratado; acuerdo solemne y vinculante entre partes, ya sea divino-humano o entre naciones', 'Uno de los sustantivos de mayor peso teológico en la Biblia hebrea, בְּרִית aparece 284 veces para designar un acuerdo solemne y vinculante. Cubre todo el arco de la teología pactual de la Escritura: las promesas de Dios a Noé (Gn 9:13), Abraham (Gn 15:18), Moisés en el Sinaí y David, así como el nuevo pacto profetizado (Jr 31:31). Más allá del eje divino-humano, también denota tratados políticos entre naciones (Jos 9:6) y pactos personales entre individuos (Gn 31:44). La traducción en diversas lenguas refleja la gravedad del concepto: español pacto, francés alliance, alemán Bund, cada uno con resonancias de obligación solemne.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1288', 'spa', 'Bendecir, arrodillarse; Piel: invocar bendición; Qal pasivo: bendito; eufemísticamente: maldecir, blasfemar', 'Pocas palabras hebreas abarcan un campo semántico tan dramático como בָּרַךְ. En su raíz física significa arrodillarse (2 Cr 6:13; Sal 95:6), y desde esa postura de reverencia el tronco Piel desarrolla el sentido dominante de otorgar o invocar bendición — ya sea Dios bendiciendo a la humanidad (Gn 1:28), personas bendiciendo a Dios en adoración, o una persona bendiciendo a otra. El participio Qal pasivo בָּרוּךְ (''bendito'') se convirtió en la exclamación litúrgica estándar de Israel. De manera llamativa, בָּרַךְ también funciona como eufemismo para maldecir a Dios (Job 1:11; 1 R 21:10), una inversión escribal que revela cuán profundamente la cultura veneraba el acto de bendecir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1289', 'spa', 'Arrodillarse, bendecir o alabar; verbo arameo usado en Daniel para arrodillarse en oración y bendecir el nombre de Dios.', 'Cognado arameo del ubicuo hebreo בָּרַךְ, este verbo abarca la misma doble gama de arrodillamiento físico y bendición verbal. Daniel se arrodilla sobre sus rodillas en oración (Dn 6:10), mientras que en otros pasajes la palabra expresa alabanza y bendición dirigidas a Dios (Dn 2:19-20; 4:34). Las glosas en español revelan esta dualidad con claridad: ''arrodillado'' junto a ''bendije/bendijo''. Que una sola raíz abarque desde la postura postrada de oración hasta la doxología exaltada captura algo profundo sobre la adoración bíblica: bendecir a Dios comienza con doblar la rodilla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1290', 'spa', 'Rodilla — articulación corporal usada al arrodillarse en adoración, súplica y en expresiones idiomáticas de nacimiento y bendición', 'Rodilla — articulación corporal usada al arrodillarse en adoración, súplica y en expresiones idiomáticas de nacimiento y bendición');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1293', 'spa', 'Bendición: favor divino, bendición pronunciada o bien prometido otorgado a alguien; en contadas ocasiones, un regalo concreto u oferta de paz.', 'Bendición: favor divino, bendición pronunciada o bien prometido otorgado a alguien; en contadas ocasiones, un regalo concreto u oferta de paz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1294', 'spa', 'Beraca — un guerrero que se unió a David y un valle donde Judá bendijo a Dios', 'El nombre Beraca significa ''bendición'' y aparece en dos contextos: un guerrero benjaminita que desertó hacia David en Siclag (1 Cr 12:3), y el Valle de Beraca donde el ejército de Josafat se reunió para bendecir al Señor tras su milagrosa victoria sobre Moab y Amón (2 Cr 20:26, mencionado dos veces). El nombre del valle conmemora aquel momento de acción de gracias. Tanto la persona como el lugar dan testimonio de la bendición de Dios: uno mediante la lealtad durante los años de David en el desierto, el otro mediante la liberación en batalla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1295', 'spa', 'Estanque, piscina — un depósito natural o construido de agua estancada, frecuentemente un punto de referencia cívico. Designa un estanque o piscina, y', 'Estanque, piscina — un depósito natural o construido de agua estancada, frecuentemente un punto de referencia cívico. Designa un estanque o piscina, ya sea de formación natural o construido artificialmente para la recolección de agua. En el texto bíblico, estanques específicos sirven como hitos cívicos notables: el estanque de Gabaón donde los hombres de Abner y Joab se enfrentaron (2 S 2:13), el estanque donde se lavó el carro de Acab (1 R 22:38), el famoso estanque del acueducto de Ezequías (2 R 20:20; Is 22:9-11) y los estanques que Salomón construyó para regar sus jardines (Ec 2:6). El símil vívido de Nahúm compara a Nínive en fuga con un estanque cuyas aguas se escurren (Nah 2:9). La palabra también aparece en la tierna imaginería del Cantar de los Cantares 7:5.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1296', 'spa', 'Berequías — nombre propio teofórico que significa «el SEÑOR ha bendecido», llevado por varios levitas, funcionarios y el padre del profeta Zacarías. B', 'Berequías — nombre propio teofórico que significa «el SEÑOR ha bendecido», llevado por varios levitas, funcionarios y el padre del profeta Zacarías. Berequías (בֶּרֶכְיָה, «el SEÑOR ha bendecido») es un nombre personal teofórico que llevan al menos siete individuos en el Antiguo Testamento, siendo el más célebre el padre del profeta Zacarías (Zac 1:1, 7). Entre los demás: un descendiente de David en la línea real postexílica (1 Cr 3:20); un músico levita, padre de Asaf el cantor (1 Cr 6:39; 15:17); un portero del arca (1 Cr 15:23); un levita que se estableció en Jerusalén después del exilio (1 Cr 9:16); y dos hombres involucrados en la reconstrucción del muro de Nehemías: Mesulam hijo de Berequías reparó secciones del muro (Neh 3:4, 30). La teología de bendición del nombre armoniza con la esperanza profética que Zacarías proclamó.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H1297', 'spa', 'Pero, sin embargo, no obstante; conjunción adversativa aramea que introduce un contraste o matización.', 'Adverbio adversativo arameo que significa ''pero'' o ''sin embargo'', empleado para introducir una declaración contrastante o que matiza lo anterior. Aparece cinco veces en Daniel y Esdras, frecuentemente pivotando de un escenario negativo a una contraacción divina. En Daniel 2:28 gira de la incapacidad humana a la revelación divina: ''pero hay un Dios en el cielo que revela misterios''. En Daniel 4:15 y 4:23 matiza la orden de destruir el árbol: ''pero dejad el tocón''. El cognado siríaco cumple la misma función contrastiva, traduciendo el griego πλήν en el Nuevo Testamento.');